151:         extends AbstractActionNewModelElement {
152: 
153:         /**
154:          * The constructor.
155:          */
156:         public ActionAddAttributeToDataType() {
157:             super("button.new-enumeration-literal");
158:             putValue(Action.NAME, Translator.localize(
159:                 "button.new-enumeration-literal"));
160:         }
161: 
162:         /**
163:          * @see java.awt.event.ActionListener#actionPerformed(java.awt.event.ActionEvent)
164:          */
165:         public void actionPerformed(ActionEvent e) {
166:             Object target = TargetManager.getInstance().getModelTarget();
167:             if (org.argouml.model.ModelFacade.isAClassifier(target)) {
168:                 Object stereo = null;
169:                 if (ModelFacade.getStereotypes(target).size() > 0) {
170:                     stereo =
171:                         ModelFacade.getStereotypes(target).iterator().next();
172:                 }
173:                 if (stereo == null) {
174:                     //  if there is not an enumeration stereotype as
175:                     //     an immediate child of the model, add one
176:                     Object model = ModelFacade.getModel(target);
177:                     Object ownedElement;
178:                     boolean match = false;
179:                     if (model != null) {
180:                         Collection ownedElements =
181:                             ModelFacade.getOwnedElements(model);
182:                         if (ownedElements != null) {
183:                             Iterator iter = ownedElements.iterator();
184:                             while (iter.hasNext()) {
185:                                 ownedElement = iter.next();
186:                                 if (ModelFacade.isAStereotype(ownedElement)) {
187:                                     stereo = /* (MStereotype) */ownedElement;
188:                                     String stereoName =
189:                                         ModelFacade.getName(stereo);
190:                                     if (stereoName != null
191:                                         && stereoName.equals("enumeration")) {
192:                                         match = true;
193:                                         break;
194:                                     }
195:                                 }
196:                             }
197:                             if (!match) {
198:                                 stereo =
199:                                     Model.getExtensionMechanismsFactory()
200:                                         .createStereotype();
201:                                 ModelFacade.setName(stereo, "enumeration");
202:                                 ModelFacade.addOwnedElement(model, stereo);
203:                             }
204:                             ModelFacade.setStereotype(target, stereo);
205:                         }
206:                     }
207:                 }
208: 
209:                 Collection propertyChangeListeners =
210:                     ProjectManager.getManager()
211:                     	.getCurrentProject().findFigsForMember(target);
212:                 Object intType =
213:                     ProjectManager.getManager()
214:                     	.getCurrentProject().findType("int");
215:                 Object model =
216:                     ProjectManager.getManager()
217:                     	.getCurrentProject().getModel();
218:                 Object attr =
219:                     Model.getCoreFactory().buildAttribute(target,
220:                             model, intType, propertyChangeListeners);
221:                 ModelFacade.setChangeable(attr, false);
222:                 TargetManager.getInstance().setTarget(attr);
223:                 super.actionPerformed(e);
224:             }
225:         }
226:     }
