46: /**
47:  * Class to display graphics for a UML ActionState in a diagram.
48:  * It contains a multiline textfield for the Entry Action Expression.
49:  *
50:  * @author ics 125b silverbullet team
51:  */
52: public class FigActionState extends FigStateVertex {
53: 
54:     ////////////////////////////////////////////////////////////////
55:     // constants
56: 
57:     private static final int PADDING = 8;
58: 
59:     ////////////////////////////////////////////////////////////////
60:     // instance variables
61: 
62:     private FigRRect cover;
63: 
64:     private NotationProvider4 notationProvider;
65: 
66:     ////////////////////////////////////////////////////////////////
67:     // constructors
68: 
69:     /**
70:      * Constructor FigActionState.
71:      */
72:     public FigActionState() {
73:         setBigPort(new FigRRect(10 + 1, 10 + 1, 90 - 2, 25 - 2, Color.cyan,
74:                 Color.cyan));
75:         ((FigRRect) getBigPort()).setCornerRadius(getBigPort().getHeight() / 2);
76:         cover = new FigRRect(10, 10, 90, 25, Color.black, Color.white);
77:         cover.setCornerRadius(getHeight() / 2);
78: 
79:         // overrule the single-line namefig created by the parent
80:         setNameFig(new FigMultiLineText(10 + PADDING, 10, 90 - PADDING * 2, 25,
81:                 true));
82:         getNameFig().setLineWidth(0);
83:         getNameFig().setText(placeString());
84:         getNameFig().setBotMargin(7); // make space for the clarifier
85:         getNameFig().setTopMargin(7); // for vertical symmetry
86:         getNameFig().setRightMargin(4); // margin between text and border
87:         getNameFig().setLeftMargin(4);
88:         getNameFig().setJustification(FigText.JUSTIFY_CENTER);
89: 
90:         getBigPort().setLineWidth(0);
91: 
92:         // add Figs to the FigNode in back-to-front order
93:         addFig(getBigPort());
94:         addFig(cover);
95:         addFig(getNameFig());
96: 
97:         //setBlinkPorts(false); //make port invisble unless mouse enters
98:         Rectangle r = getBounds();
99:         setBounds(r.x, r.y, r.width, r.height);
100:     }
101: 
102:     /**
103:      * Constructor FigActionState.
104:      *
105:      * @param gm ignored!
106:      * @param modelElement owner
107:      */
108:     public FigActionState(GraphModel gm, Object modelElement) {
109:         this();
110:         setOwner(modelElement);
111:     }
112: 
113:     /**
114:      * @see org.argouml.uml.diagram.state.ui.FigStateVertex#initNotationProviders(java.lang.Object)
115:      */
116:     protected void initNotationProviders(Object modelElement) {
117:         super.initNotationProviders(modelElement);
118:         if (Model.getFacade().isAActionState(modelElement)) {
119:             notationProvider =
120:                 NotationProviderFactory2.getInstance().getNotationProvider(
121:                     NotationProviderFactory2.TYPE_ACTIONSTATE, this, modelElement);
122:         }
123:     }
124: 
125:     /**
126:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#placeString()
127:      */
128:     public String placeString() {
129:         return "new ActionState";
130:     }
131: 
132:     /**
133:      * @see java.lang.Object#clone()
134:      */
135:     public Object clone() {
136:         FigActionState figClone = (FigActionState) super.clone();
137:         Iterator it = figClone.getFigs().iterator();
138:         figClone.setBigPort((FigRRect) it.next());
139:         figClone.cover = (FigRRect) it.next();
140:         figClone.setNameFig((FigText) it.next());
141:         return figClone;
142:     }
