145:     // Fig accessors
146: 
147:     /**
148:      * @see org.tigris.gef.presentation.Fig#getMinimumSize()
149:      */
150:     public Dimension getMinimumSize() {
151:         Dimension nameDim = getNameFig().getMinimumSize();
152:         int w = nameDim.width + PADDING * 2;
153:         int h = nameDim.height + PADDING;
154:         return new Dimension(w, h);
155:     }
