157:     /**
158:      * @see org.tigris.gef.presentation.Fig#setBoundsImpl(int, int, int, int)
159:      *
160:      * Override setBounds to keep shapes looking right.
161:      */
162:     protected void setBoundsImpl(int x, int y, int w, int h) {
163:         if (getNameFig() == null) {
164:             return;
165:         }
166:         Rectangle oldBounds = getBounds();
167: 
168:         getNameFig().setBounds(x + PADDING, y, w - PADDING * 2, h - PADDING);
169:         getBigPort().setBounds(x + 1, y + 1, w - 2, h - 2);
170:         cover.setBounds(x, y, w, h);
171:         ((FigRRect) getBigPort()).setCornerRadius(h);
172:         cover.setCornerRadius(h);
173: 
174:         calcBounds();
175:         updateEdges();
176:         firePropChange("bounds", oldBounds, getBounds());
177:     }
