235:     /**
236:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
237:      */
238:     protected void modelChanged(PropertyChangeEvent mee) {
239:         super.modelChanged(mee);
240:         if (mee instanceof AddAssociationEvent
241:                 || mee instanceof AttributeChangeEvent) {
242:             if (mee.getSource() == getOwner()
243:                 && mee.getPropertyName().equals("entry")) {
244:                 if (mee.getNewValue() != null) {
245:                     addElementListener(mee.getNewValue(), "script");
246:                 }
247:                 updateNameText();
248:                 damage();
249:             } else {
250:                 if (getOwner() != null
251:                         && Model.getFacade().getEntry(getOwner()) == mee
252:                                 .getSource()) {
253:                     updateNameText();
254:                     damage();
255:                 }
256:             }
257:         } else if (mee instanceof RemoveAssociationEvent) {
258:             if (mee.getOldValue() != null
259:                     && mee.getPropertyName().equals("entry")) {
260:                 removeElementListener(mee.getOldValue());
261:                 updateNameText();
262:                 damage();
263:             }
264:         }
265:     }
266: 
267: 
268:     /**
269:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
270:      */
271:     protected void updateNameText() {
272:         if (notationProvider != null) {
273:             getNameFig().setText(notationProvider.toString());
274:         }
275:     }
276: 
277: 
278:     /**
279:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEdited(org.tigris.gef.presentation.FigText)
280:      */
281:     protected void textEdited(FigText ft) throws PropertyVetoException {
282:         ft.setText(notationProvider.parse(ft.getText()));
283:     }
284: 
285:     /**
286:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEditStarted(org.tigris.gef.presentation.FigText)
287:      */
288:     protected void textEditStarted(FigText ft) {
289:         if (ft == getNameFig()) {
290:             showHelp(notationProvider.getParsingHelp());
291:         }
292:     }
293: 
294:     /**
295:      * The UID.
296:      */
297:     private static final long serialVersionUID = -3526461404860044420L;
298: } /* end class FigActionState */
