301:   public Object addOutgoingTrans(MutableGraphModel gm, MStateVertex cls,
302:                                  MStateVertex newCls) {
303:     return gm.connect(cls, newCls, MTransition.class);
304:   }
305: 
306:   public Object addIncomingTrans(MutableGraphModel gm, MStateVertex cls,
307:                                  MStateVertex newCls) {
308:     return gm.connect(newCls, cls, MTransition.class);
309:   }
