175:     if (hand.index < 10) {
176:       _paintButtons = false;
177:       super.dragHandle(mX, mY, anX, anY, hand);
178:       return;
179:     }
180:     int cx = _content.getX(), cy = _content.getY();
181:     int cw = _content.getWidth(), ch = _content.getHeight();
182:     int newX = cx, newY = cy, newW = cw, newH = ch;
183:     Dimension minSize = _content.getMinimumSize();
184:     int minWidth = minSize.width, minHeight = minSize.height;
185:     Class edgeClass = null;
186:     Class nodeClass = MActionStateImpl.class;
187: 
188:     Editor ce = Globals.curEditor();
189:     GraphModel gm = ce.getGraphModel();
190:     if (!(gm instanceof MutableGraphModel)) return;
191:    
192:     MutableGraphModel mgm = (MutableGraphModel) gm;
193: 
194:     int bx = mX, by = mY;
195:     boolean reverse = false;
196:     switch (hand.index) {
197:     case 12: //add outgoing
198:       edgeClass = MTransition.class;
199:       by = cy + ch/2;
200:       bx = cx + cw;
201:       break;
202:     case 13: // add incoming
203:       edgeClass = MTransition.class;
204:       reverse = true;
205:       by = cy + ch/2;
206:       bx = cx;
207:       break;
208:      case 14: // add incoming
209:       edgeClass = MTransition.class;
210:       reverse = true;
211:       by = cy ;
212:       bx = cx + cw/2;
213:       break;
214:      case 15: // add outgoing
215:       edgeClass = MTransition.class;
216:       by = cy + ch;
217:       bx = cx + cw/2;
218:       break;
219:     default:
220:       cat.warn("invalid handle number");
221:       break;
222:     }
223:     if (edgeClass != null && nodeClass != null) {
224:       ModeCreateEdgeAndNode m = new
225: 	ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, false);
226:       m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
227:       ce.mode(m);
228:     }
229:   }
