171:             paintButtonLeft(compos, g, cx + cw, cy + ch/2, 12);
172:             paintButtonRight(compos, g, cx, cy + ch/2, 13);
173:             paintButtonRight(selfassoc, g, cx, cy + ch - 10, 14);
174:         }
175:         else {
