64: public class SelectionClass extends SelectionWButtons {
65:     protected static Category cat = 
66:         Category.getInstance(SelectionClass.class);
67:     ////////////////////////////////////////////////////////////////
68:     // constants
69:     public static Icon inherit = 
70:         ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Generalization");
71: 
72:     public static Icon assoc = 
73:         ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Association");
74: 
