76:         ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("CompositeAggregation");
77: 
78:     public static Icon selfassoc =
79:         ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("SelfAssociation");
80:         
