84:     // instance variables
85:     protected boolean _useComposite = false;
86:     
87: 
88: 
89:     ////////////////////////////////////////////////////////////////
90:     // constructors
91: 
92:     /** Construct a new SelectionClass for the given Fig */
93:     public SelectionClass(Fig f) { super(f); }
94: 
95:     /** Return a handle ID for the handle under the mouse, or -1 if
96:      *  none. Needs-More-Work: in the future, return a Handle instance or
97:      *  null. <p>
98:      *  <pre>
99:      *   0-------1-------2
100:      *   |               |
101:      *   3               4
102:      *   |               |
103:      *   5-------6-------7
104:      * </pre>
105:      */
106:     public void hitHandle(Rectangle r, Handle h) {
107:         super.hitHandle(r, h);
108:         if (h.index != -1) return;
109:         if (!_paintButtons) return;
110:         Editor ce = Globals.curEditor();
111:         SelectionManager sm = ce.getSelectionManager();
112:         if (sm.size() != 1) return;
113:         ModeManager mm = ce.getModeManager();
114:         if (mm.includes(ModeModify.class) && _pressedButton == -1) return;
115:         int cx = _content.getX();
116:         int cy = _content.getY();
117:         int cw = _content.getWidth();
118:         int ch = _content.getHeight();
119:         int iw = inherit.getIconWidth();
120:         int ih = inherit.getIconHeight();
121:         int aw = assoc.getIconWidth();
122:         int ah = assoc.getIconHeight();
123:         int saw = selfassoc.getIconWidth();
124:         int sah = selfassoc.getIconHeight();
125: 
126:         if (hitAbove(cx + cw/2, cy, iw, ih, r)) {
127:             h.index = 10;
128:             h.instructions = "Add a superclass";
129:         }
130:         else if (hitBelow(cx + cw/2, cy + ch, iw, ih, r)) {
131:             h.index = 11;
132:             h.instructions = "Add a subclass";
133:         }
134:         else if (hitLeft(cx + cw, cy + ch/2, aw, ah, r)) {
135:             h.index = 12;
136:             h.instructions = "Add an associated class";
137:         }
138:         else if (hitRight(cx, cy + ch/2, aw, ah, r)) {
139:             h.index = 13;
140:             h.instructions = "Add an associated class";
141:         }
142:         else if (hitRight(cx, cy + ch - 10, saw, sah, r)) {
143:             h.index = 14;
144:             h.instructions = "Add a self association";
145:         }
146:         else {
147:             h.index = -1;
148:             h.instructions = "Move object(s)";
149:         }
150:     }
151: 
152: 
153:     /** Paint the handles at the four corners and midway along each edge
154:      * of the bounding box.  */
155:     public void paintButtons(Graphics g) {
156:         int cx = _content.getX();
157:         int cy = _content.getY();
158:         int cw = _content.getWidth();
159:         int ch = _content.getHeight();
160: 
161:         // The next two lines are necessary to get the GraphModel,
162:         // in the DeploymentDiagram there are no Generalizations
163:         Editor ce = Globals.curEditor();
164:         GraphModel gm = ce.getGraphModel();
165: 
166:         if (!(gm instanceof DeploymentDiagramGraphModel)) {
167:             paintButtonAbove(inherit, g, cx + cw/2, cy, 10);
168:             paintButtonBelow(inherit, g, cx + cw/2, cy + ch, 11);
169:         }
170:         if (_useComposite) {
171:             paintButtonLeft(compos, g, cx + cw, cy + ch/2, 12);
172:             paintButtonRight(compos, g, cx, cy + ch/2, 13);
173:             paintButtonRight(selfassoc, g, cx, cy + ch - 10, 14);
174:         }
175:         else {
176:             paintButtonLeft(assoc, g, cx + cw, cy + ch/2, 12);
177:             paintButtonRight(assoc, g, cx, cy + ch/2, 13);
178:             paintButtonRight(selfassoc, g, cx, cy + ch - 10, 14);
179:         }
180:     }
