332:     public Object createSuperClass(MutableGraphModel mgm, MClass cls,
333:                                    MClass newCls) {
334:         return mgm.connect(cls, newCls, MGeneralization.class);
335:     }
336: 
337:     public Object createEdgeRight(MutableGraphModel mgm, MClass cls,
338:                                   MClass newCls) {
339:         return mgm.connect(newCls, cls, MGeneralization.class);
340:     }
341: 
342:     public Object addAssocClassRight(MutableGraphModel mgm, MClass cls,
343:                                      MClass newCls) {
344:         return mgm.connect(cls, newCls, MAssociation.class);
345:     }
346: 
347:     public Object addAssocClassLeft(MutableGraphModel mgm, MClass cls,
348:                                     MClass newCls) {
349:         return mgm.connect(newCls, cls, MAssociation.class);
350:     }
