332:     public Object createEdgeAbove(MutableGraphModel mgm, MClass cls,
333:                                   MClass newCls) {
334:         return mgm.connect(cls, newCls, MGeneralization.class);
335:     }
336: 
337:     public Object createEdgeBelow(MutableGraphModel mgm, MClass cls,
338:                                   MClass newCls) {
339:         return mgm.connect(newCls, cls, MGeneralization.class);
340:     }
