81: 	    new FigCircle(x, y, width, height, Color.black, Color.white);
82: 	_inCircle =
83: 	    new FigCircle(
84: 			  x + 5,
85: 			  y + 5,
86: 			  width - 10,
87: 			  height - 10,
88: 			  handleColor,
89: 			  Color.black);
90: 
91: 	_outCircle.setLineWidth(1);
92: 	_inCircle.setLineWidth(0);
93: 
94: 	setNameFig(new FigText(x + 10, y + 22, 0, 21, true));
95: 	getNameFig().setFilled(false);
96: 	getNameFig().setLineWidth(0);
97: 	getNameFig().setFont(LABEL_FONT);
98: 	getNameFig().setTextColor(Color.black);
99: 	getNameFig().setMultiLine(false);
100: 	getNameFig().setAllowsTab(false);
101: 	getNameFig().setJustificationByName("center");
102: 		
103: 	addFig(_bigPort);
104: 	addFig(_outCircle);
105: 	addFig(_inCircle);
106: 	addFig(getNameFig());
107: 
108: 	setBlinkPorts(false); //make port invisble unless mouse enters
109: 	Rectangle r = getBounds();
110:     }
