25: package org.argouml.application.security;
26: 
27: // Import the following classes fully qualified to ensure that
28: // no one can short-circuit our intended inheritance.
29: import java.util.PropertyPermission;
30: import java.security.Permission;
31: 
32: import org.apache.log4j.Logger;
33: import org.argouml.util.osdep.OsUtil;
34: 
35: /**
36:  * The Argo custom security manager.
37:  *
38:  *  Since Argo is an open-source product, the concept of a
39:  *  security manager may seem odd.  This class is not intended
40:  *  to provide security in the standard way that Java programmers
41:  *  think of, in the context of Applets, for example.
42:  *
43:  *  Rather, it is intended to protect Argo from accidental modifications
44:  *  to its own environment by external modules.
45:  *
46:  *  One of the areas this is necessary is to protect from the
47:  *  {@link java.lang.System#exit(int)} or
48:  *  {@link java.lang.Runtime#exit(int)} calls.
49:  *
50:  *  Another is to prevent modules from replacing the awt exception
51:  *  trapping hook so that we are able to properly catch any
52:  *  ArgoSecurityExceptions and prevent the stack trace when
53:  *  we desire.
54:  *
55:  *  @author Thierry Lach
56:  *  @since 0.9.4
57:  *  @stereotype singleton
58:  */
59: public final class ArgoSecurityManager extends SecurityManager
60: {
61:     private static final Logger LOG =
62: 	Logger.getLogger(ArgoSecurityManager.class);
63: 
64:     /**
65:      * true if we are allowed to exit.<p>
66:      *
67:      * This is set to false from main() just before we start the ball rolling
68:      * for the GUI.<p>
69:      *
70:      * This means that all applications that doesn't start from main i.e.
71:      * when running JUnit test cases and batch commands, are allowed to
72:      * exit immediatly.
73:      */
74:     private boolean allowExit = true;
75: 
76:     /** The only allowed instance. */
77:     private static final ArgoSecurityManager SINGLETON =
78: 	new ArgoSecurityManager();
79: 
80:     /**
81:      * Accessor for the instance.
82:      */
83:     public static final ArgoSecurityManager getInstance() {
84:         return SINGLETON;
85:     }
86: 
87:     /** Don't allow it to be instantiated from the outside. */
88:     private ArgoSecurityManager() {
89:     }
90: 
91:     public void checkPermission(Permission perm) {
92:         // TODO:  
93: 	// Don't allow write access to <code>sun.awt.exception.handler</code>
94: 	if (perm.getClass().equals(PropertyPermission.class)) {
95: 	    if ("sun.awt.exception.handler".equals(perm.getName())) {
96: 	        PropertyPermission pp = (PropertyPermission) perm;
97: 		if ("write".equals(pp.getActions())
98: 		    && (!OsUtil.isMac())) {
99: 		    // Don't allow this one to be trapped
100: 		    // by using ArgoSecurityException.
101: 		    LOG.debug("Violating Permission Name: " + pp.getName());
102: 		    throw new SecurityException();
103: 		}
104: 	    }
105: 	}
106: 	// Don't allow anything to exit that we don't know about.
107: 	else if (perm.getClass().equals(java.lang.RuntimePermission.class)) {
108: 	    RuntimePermission rp = (RuntimePermission) perm;
109:             // Uncomment for more information about what happens...
110: 	    LOG.debug("RuntimePermission: " + rp.getName() 
111: 		      + " - '" + rp.getActions() + "'");
112: 	    if ("exitVM".equals(rp.getName())) {
113: 		if (!getInstance().getAllowExit()) {
114: 		    throw new ArgoSecurityException(true);
115: 		}
116: 	    }
117: 	}
118:     }
119: 
120:     public boolean getAllowExit() {
121:         return allowExit;
122:     }
123: 
124:     public void setAllowExit(boolean myAllowExit) {
125:         allowExit = myAllowExit;
126:     }
127: }
