568:     /** get a list of offenders and display the according diagram, aka
569:      *  implement a method which jumps to the offender.
570:      *  TODO: this probably needs a lot of work, as the code looks
571:      *  as if it can only jump to diagram offenders
572:      *
573:      *  @param dms vector of offenders
574:      *  @see org.argouml.cognitive.ui.ToDoPane
575:      */
576:     public void jumpToDiagramShowing(VectorSet dms) {
577:         if (dms.size() == 0) {
578:             return;
579:         }
580:         Object first = dms.elementAt(0);
581:         if (first instanceof Diagram && dms.size() > 1) {
582:             setTarget(first);
583:             setTarget(dms.elementAt(1));
584:             return;
585:         }
586:         if (first instanceof Diagram && dms.size() == 1) {
587:             setTarget(first);
588:             return;
589:         }
590:         Vector diagrams =
591:             ProjectManager.getManager().getCurrentProject().getDiagrams();
592:         Object target = _editorPane.getTarget();
593:         if ((target instanceof Diagram)
594:             && ((Diagram) target).countContained(dms) == dms.size()) {
595:             setTarget(first);
596:             return;
597:         }
598: 
599:         Diagram bestDiagram = null;
600:         int bestNumContained = 0;
601:         for (int i = 0; i < diagrams.size(); i++) {
602:             Diagram d = (Diagram) diagrams.elementAt(i);
603:             int nc = d.countContained(dms);
604:             if (nc > bestNumContained) {
605:                 bestNumContained = nc;
606:                 bestDiagram = d;
607:             }
608:             if (nc == dms.size())
609:                 break;
610:         }
611:         if (bestDiagram != null) {
612:             setTarget(bestDiagram);
613:             setTarget(first);
614:         }
615:         // making it possible to jump to the modelroot
616:         if (first.equals(ProjectManager.getManager().getCurrentProject()
617: 			 .getRoot()))
618: 	{
619:             setTarget(first);
620:         }
621:     }
