223: 	    makeDetailsPane(BorderSplitPane.EAST,  Vertical.getInstance());
224:         _southPane =
225: 	    makeDetailsPane(BorderSplitPane.SOUTH, Horizontal.getInstance());
226:         _southEastPane =
227: 	    makeDetailsPane(BorderSplitPane.SOUTHEAST,
