161:     /**
162:      * Create a note for a given model element.
163:      * @deprecated as of 0.17.1 nobody should use this constructor since
164:      * it not only constructs the fig but also the model behind it.
165:      * That should not be done by a fig which is only a view to the model
166:      * @param element The annotated model element.
167:      */
168:     public FigComment(Object element) {
169:         this(); // Construct the figure.
170: 
171:         if (!ModelFacade.isAModelElement(element)) {
172:             throw new IllegalArgumentException();
173:         }
174: 
175: 	// Create a new Comment node.
176:         Object comment =
177: 	    Model.getCoreFactory().createComment();
178:         setOwner(comment); // Set it as the owner of the figure.
179: 	// Tell the annotated element, that it has a comment now.
180:         ModelFacade.addComment(element, comment);
181: 
182:         // Notes in statechart diagrams need a special treatment, cause
183:         // the nodes in them don't necessary have a namespace, where
184:         // we could add the note. So I added this hack... :-(
185:         // Andreas Rueckert <a_rueckert@gmx.net>
186:         if (ModelFacade.isAStateVertex(element)) {
187: 
188: 	    // If the current target is a statechart diagram, we have to
189: 	    // check, if we are editing the diagram.
190:             ProjectBrowser pb = ProjectBrowser.getInstance();
191:             if (TargetManager.getInstance().getTarget()
192:                     instanceof UMLStateDiagram) {
193:                 StateDiagramGraphModel gm =
194: 		    (StateDiagramGraphModel)
195: 		    (((UMLStateDiagram) TargetManager.getInstance()
196: 		            .getTarget()).getGraphModel());
197: 		// We are editing, so we set the Namespace directly.
198:                 ModelFacade.setNamespace(comment, gm.getNamespace());
199:             }
200:         } else {
201: 	    // Add the comment to the same namespace as the annotated element.
202:             ModelFacade.setNamespace(comment,
203:                     ModelFacade.getNamespace(element));
204:         }
205: 
206:         storeNote(placeString()); // Set the default text for this figure type.
207:     }
