500:     /**
501:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
502:      */
503:     public void setBounds(int px, int py, int w, int h) {
504:         if (text == null) {
505:             return;
506:         }
507: 
508:         Rectangle oldBounds = getBounds();
509: 
510:         // Resize the text figure
511:         text.setBounds(px + 2, py + 2, w - 4 - gapY, h - 4);
512: 
513:         // Resize the big port around the figure
514:         getBigPort().setBounds(px, py, w, h);
515: 
516:         // Since this is a complex polygon, there's no easy way to resize it.
517:         Polygon newPoly = new Polygon();
518:         newPoly.addPoint(px, py);
519:         newPoly.addPoint(px + w - 1 - gapY, py);
520:         newPoly.addPoint(px + w - 1, py + gapY);
521:         newPoly.addPoint(px + w - 1, py + h - 1);
522:         newPoly.addPoint(px, py + h - 1);
523:         newPoly.addPoint(px, py);
524:         body.setPolygon(newPoly);
525: 
526:         // Just move the corner to it's new position.
527:         urCorner.setBounds(px + w - 1 - gapY, py, gapY, gapY);
528: 
529:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
530:         firePropChange("bounds", oldBounds, getBounds());
531:     }
