304:     /**
305:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
306:      */
307:     public void propertyChange(PropertyChangeEvent pve) {
308:         Object src = pve.getSource();
309:         String pName = pve.getPropertyName();
310:         if (pName.equals("editing")
311: 	    && Boolean.FALSE.equals(pve.getNewValue())) {
312:             try {
313:                 //parse the text that was edited
314:                 textEdited((FigText) src);
315:                 // resize the FigNode to accomodate the new text
316:                 Rectangle bbox = getBounds();
317:                 Dimension minSize = getMinimumSize();
318:                 bbox.width = Math.max(bbox.width, minSize.width);
319:                 bbox.height = Math.max(bbox.height, minSize.height);
320:                 setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
321:                 endTrans();
322:             } catch (PropertyVetoException ex) {
323:                 LOG.error("could not parse and use the text entered "
324: 			  + "in figcomment", ex);
325:             }
326:         } else {
327:             super.propertyChange(pve);
328:         }
329:     }
