452:     ////////////////////////////////////////////////////////////////
453:     // accessor methods
454: 
455:     /**
456:      * Store a note in the associated model element.
457:      *
458:      * @param note The note to store.
459:      */
460:     public final void storeNote(String note) {
461:         if (getOwner() != null) {
462:             ModelFacade.setName(getOwner(), note);
463:         }
464:     }
465: 
466:     /**
467:      * Retrieve the note from the associated model element.
468:      *
469:      * @return The note from the associated model element.
470:      */
471:     public final String retrieveNote() {
472:         return (getOwner() != null)
473: 	    ? org.argouml.model.ModelFacade.getName(getOwner())
474: 	    : null;
475:     }
476: 
477:     /**
478:      * @see org.tigris.gef.presentation.Fig#getUseTrapRect()
479:      */
480:     public boolean getUseTrapRect() {
481:         return true;
482:     }
483: 
484:     /**
485:      * Get the minimum size for the note figure.
486:      *
487:      * @return The minimum size for the note figure.
488:      */
489:     public Dimension getMinimumSize() {
490: 
491:         // Get the size of the text field.
492:         Dimension textMinimumSize = text.getMinimumSize();
493: 
494:         // And add the gaps around the textfield to get the minimum
495:         // size of the note.
496:         return new Dimension(textMinimumSize.width + 4 + gapY,
497: 			     textMinimumSize.height + 4);
498:     }
499: 
500:     /**
501:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
502:      */
503:     public void setBounds(int px, int py, int w, int h) {
504:         if (text == null) {
505:             return;
506:         }
507: 
508:         Rectangle oldBounds = getBounds();
509: 
510:         // Resize the text figure
511:         text.setBounds(px + 2, py + 2, w - 4 - gapY, h - 4);
512: 
513:         // Resize the big port around the figure
514:         getBigPort().setBounds(px, py, w, h);
515: 
516:         // Since this is a complex polygon, there's no easy way to resize it.
517:         Polygon newPoly = new Polygon();
518:         newPoly.addPoint(px, py);
519:         newPoly.addPoint(px + w - 1 - gapY, py);
520:         newPoly.addPoint(px + w - 1, py + gapY);
521:         newPoly.addPoint(px + w - 1, py + h - 1);
522:         newPoly.addPoint(px, py + h - 1);
523:         newPoly.addPoint(px, py);
524:         body.setPolygon(newPoly);
525: 
526:         // Just move the corner to it's new position.
527:         urCorner.setBounds(px + w - 1 - gapY, py, gapY, gapY);
528: 
529:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
530:         firePropChange("bounds", oldBounds, getBounds());
531:     }
532: 
533:     /**
534:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateBounds()
535:      */
536:     protected void updateBounds() {
537:         Rectangle bbox = getBounds();
538:         Dimension minSize = getMinimumSize();
539:         bbox.width = Math.max(bbox.width, minSize.width);
540:         bbox.height = Math.max(bbox.height, minSize.height);
541:         setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
542:     }
543: 
544:     ///////////////////////////////////////////////////////////////////
545:     // Internal methods
546: 
547:     /**
548:      * This is called after any part of the UML ModelElement (the comment) has
549:      * changed. This method automatically updates the note FigText.
550:      *
551:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
552:      */
553:     protected final void modelChanged(PropertyChangeEvent mee) {
554:         super.modelChanged(mee);
555: 
556:         String noteStr = retrieveNote();
557:         if (noteStr != null) {
558:             text.setText(noteStr);
559:         }
560:     }
561: 
562:     /**
563:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
564:      */
565:     protected void updateNoteText() {
566:         if (getOwner() != null) {
567:             String t = org.argouml.model.ModelFacade.getName(getOwner());
568:             if (t != null) {
569:                 text.setText(t);
570:                 calcBounds();
571:                 setBounds(getBounds());
572:             }
573:         }
574:     }
575: 
576: } /* end class FigComment */
