315:     /**
316:      * Creates the panels in the working area.
317:      *
318:      * @param splash true if we show  the splashscreen during startup
319:      * @return Component the area between the menu and the statusbar.
320:      *                   It contains the workarea at centre and the toolbar
321:      *                   position north, south, east or west.
322:      *
323:      */
324:     protected Component createPanels(SplashScreen splash) {
325:         if (splash != null) {
326: 	    splash.getStatusBar().showStatus(
327: 	            Translator.localize(
328: 	                    "statusmsg.bar.making-project-browser-explorer"));
329:             splash.getStatusBar().incProgress(5);
330:         }
331:         explorerPane = new NavigatorPane(splash);
332: 
333:         /* Work in progress here to allow multiple details panes with
334:         ** different contents - Bob Tarling
335:         */
336:         eastPane  =
337: 	    makeDetailsPane(BorderSplitPane.EAST,  Vertical.getInstance());
338:         southPane =
339: 	    makeDetailsPane(BorderSplitPane.SOUTH, Horizontal.getInstance());
340:         southEastPane =
341: 	    makeDetailsPane(BorderSplitPane.SOUTHEAST,
342: 			    Horizontal.getInstance());
343:         northWestPane =
344: 	    makeDetailsPane(BorderSplitPane.NORTHWEST,
345: 			    Horizontal.getInstance());
346:         northPane =
347: 	    makeDetailsPane(BorderSplitPane.NORTH, Horizontal.getInstance());
348:         northEastPane =
349: 	    makeDetailsPane(BorderSplitPane.NORTHEAST,
350: 			    Horizontal.getInstance());
351: 
352:         if (southPane != null) {
353:             detailsPanesByCompassPoint.put(BorderSplitPane.SOUTH, southPane);
354:         }
355:         if (southEastPane != null) {
356:             detailsPanesByCompassPoint.put(BorderSplitPane.SOUTHEAST,
357: 					   southEastPane);
358:         }
359:         if (eastPane != null) {
360:             detailsPanesByCompassPoint.put(BorderSplitPane.EAST, eastPane);
361:         }
362:         if (northWestPane != null) {
363:             detailsPanesByCompassPoint.put(BorderSplitPane.NORTHWEST,
364: 					   northWestPane);
365:         }
366:         if (northPane != null) {
367:             detailsPanesByCompassPoint.put(BorderSplitPane.NORTH, northPane);
368:         }
369:         if (northEastPane != null) {
370:             detailsPanesByCompassPoint.put(BorderSplitPane.NORTHEAST,
371: 					   northEastPane);
372:         }
373: 
374:         // The workarea is all the visible space except the menu,
375:         // toolbar and status bar.  Workarea is layed out as a
376:         // BorderSplitPane where the various components that make up
377:         // the argo application can be positioned.
378:         workAreaPane = new BorderSplitPane();
379:         // create the todopane
380:         if (splash != null) {
381: 	    splash.getStatusBar().showStatus(Translator.localize(
382: 		    "statusmsg.bar.making-project-browser-to-do-pane"));
383:             splash.getStatusBar().incProgress(5);
384:         }
385:         todoPane = new ToDoPane(splash);
386:         restorePanelSizes();
387: 
388:         // There are various details panes all of which could hold
389:         // different tabs pages according to users settings.
390:         // Place each pane in the required border area.
391:         Iterator it = detailsPanesByCompassPoint.entrySet().iterator();
392:         while (it.hasNext()) {
393:             Map.Entry entry = (Map.Entry) it.next();
394:             String position = (String) entry.getKey();
395:             if (entry.getValue() instanceof DetailsPane) {
396:                 DetailsPane detailsPane = (DetailsPane) entry.getValue();
397:                 TargetManager.getInstance().addTargetListener(detailsPane);
398:             }
399:             addPanel((Component) entry.getValue(), position);
400:         }
401:         addPanel(explorerPane, BorderSplitPane.WEST);
402: 
403:         getTab(TabToDo.class); // TODO: If this doesn't have side effects,
404:                                //       it can be removed alltogether.
405:         //todo.setTree(_todoPane);
406:         addPanel(todoPane, BorderSplitPane.SOUTHWEST);
407:         addPanel(editorPane, BorderSplitPane.CENTER);
408:         // Toolbar boundry is the area between the menu and the status
409:         // bar. It contains the workarea at centre and the toolbar
410:         // position north, south, east or west.
411:         JPanel toolbarBoundry = new JPanel();
412:         toolbarBoundry.setLayout(new DockBorderLayout());
413:         // TODO: - should save and restore the last positions of the toolbars
414:         toolbarBoundry.add(menuBar.getFileToolbar(), BorderLayout.NORTH);
415:         toolbarBoundry.add(menuBar.getEditToolbar(), BorderLayout.NORTH);
416:         toolbarBoundry.add(menuBar.getViewToolbar(), BorderLayout.NORTH);
417:         toolbarBoundry.add(menuBar.getCreateDiagramToolbar(),
418: 			   BorderLayout.NORTH);
419:         toolbarBoundry.add(workAreaPane, BorderLayout.CENTER);
420: 
421:         return toolbarBoundry;
422:     }
