879: 
880:             String t = MessageFormat.format(Translator.localize(
881:                 "optionpane.exit-save-changes-to"),
882:                 new Object[] {p.getName()});
883:             int response = JOptionPane.showConfirmDialog(
884:                     this, t, t, JOptionPane.YES_NO_CANCEL_OPTION);
885: 
886:             if (response == JOptionPane.CANCEL_OPTION
887:                     || response == JOptionPane.CLOSED_OPTION) {
888:                 return;
889:             }
890:             if (response == JOptionPane.YES_OPTION) {
891:                 if (ActionSaveProject.getInstance().isEnabled()) {
892:                     trySave (true);
893:                 }
894:                 if (ActionSaveProject.getInstance().isEnabled()) {
895:                     trySaveAs(false);
896:                 }
897:                 if (ActionSaveProject.getInstance().isEnabled()) {
898:                     return;
899:                 }
900:             }
901:         }
902:         Configuration.save();
903:         System.exit(0);
904:     }
