722:     /**
723:      * Given a list of offenders, displays the according diagram.
724:      * This method jumps to the diagram showing the offender,
725:      * and scrolls to make it visible.
726:      *
727:      * @param dms vector of offenders
728:      */
729:     public void jumpToDiagramShowing(Vector dms) {
730:         if (dms.size() == 0) {
731:             return;
732:         }
733:         Object first = dms.elementAt(0);
734:         if (first instanceof Diagram && dms.size() > 1) {
735:             setTarget(first);
736:             setTarget(dms.elementAt(1));
737:             return;
738:         }
739:         if (first instanceof Diagram && dms.size() == 1) {
740:             setTarget(first);
741:             return;
742:         }
743:         Vector diagrams =
744:             ProjectManager.getManager().getCurrentProject().getDiagrams();
745:         Object target = TargetManager.getInstance().getTarget();
746:         if ((target instanceof Diagram)
747:             && ((Diagram) target).countContained(dms) == dms.size()) {
748:             setTarget(first);
749:             return;
750:         }
751: 
752:         Diagram bestDiagram = null;
753:         int bestNumContained = 0;
754:         for (int i = 0; i < diagrams.size(); i++) {
755:             Diagram d = (Diagram) diagrams.elementAt(i);
756:             int nc = d.countContained(dms);
757:             if (nc > bestNumContained) {
758:                 bestNumContained = nc;
759:                 bestDiagram = d;
760:             }
761:             if (nc == dms.size()) {
762:                 break;
763:             }
764:         }
765:         if (bestDiagram != null) {
766:             if (!ProjectManager.getManager().getCurrentProject()
767:                     .getActiveDiagram().equals(bestDiagram)) {
768:                 setTarget(bestDiagram);
769:             }
770:             setTarget(first);
771:         }
772:         // making it possible to jump to the modelroot
773:         if (first.equals(ProjectManager.getManager().getCurrentProject()
774: 			 .getRoot())) {
775:             setTarget(first);
776:         }
777: 
778:         // and finally, adjust the scrollbars to show the Fig
779:         Project p = ProjectManager.getManager().getCurrentProject();
780:         if (p != null) {
781:             Object f = TargetManager.getInstance().getFigTarget();
782:             if (f instanceof Fig) {
783:                 Globals.curEditor().scrollToShow((Fig) f);
784:             }
785:         }
786:     }
