1120:     /**
1121:      * If the current project is dirty (needs saving) then this function will
1122:      * ask confirmation from the user.
1123:      * If the user indicates that saving is needed, then saving is attempted.
1124:      * See ActionExit.actionPerformed() for a very similar procedure!
1125:      *
1126:      * @return true if we can continue with opening
1127:      */
1128:     public boolean askConfirmationAndSave() {
1129:         ProjectBrowser pb = ProjectBrowser.getInstance();
1130:         Project p = ProjectManager.getManager().getCurrentProject();
1131: 
1132: 
1133:         if (p != null && ActionSaveProject.getInstance().isEnabled()) {
1134:             String t =
1135:                 MessageFormat.format(Translator.localize(
1136:                         "optionpane.open-project-save-changes-to"),
1137:                         new Object[] {p.getName()});
1138: 
1139:             int response =
1140:                 JOptionPane.showConfirmDialog(pb, t, t,
1141:                     JOptionPane.YES_NO_CANCEL_OPTION);
1142: 
1143:             if (response == JOptionPane.CANCEL_OPTION
1144:                     || response == JOptionPane.CLOSED_OPTION) {
1145:                 return false;
1146:             }
1147:             if (response == JOptionPane.YES_OPTION) {
1148: 
1149:                 if (ActionSaveProject.getInstance().isEnabled()) {
1150:                     trySave(true);
1151:                 }
1152:                 if (ActionSaveProject.getInstance().isEnabled()) {
1153:                     trySaveAs(false);
1154:                 }
1155:                 if (ActionSaveProject.getInstance().isEnabled()) {
1156:                     return false;
1157:                 }
1158:             }
1159:         }
1160:         return true;
1161:     }
