1308:      *               false if run in commandline mode
1309:      */
1310:     private void reportError(String message, boolean showUI) {
1311:         if (showUI) {
1312:             JOptionPane.showMessageDialog(
1313:                       ProjectBrowser.getInstance(),
1314:                       message,
1315:                       "Error",
1316:                       JOptionPane.ERROR_MESSAGE);
