1324:      *
1325:      * @param attemptingTo What we were doing when the error occured.
1326:      * @param message the message to display.  Only used in commandline mode.
1327:      * @param showUI true if an error message may be shown to the user,
1328:      *               false if run in commandline mode
1329:      * @param ex The exception that was thrown.
1330:      */
1331:     private void reportError(String attemptingTo, String message,
1332:                     boolean showUI, Throwable ex) {
1333:         if (showUI) {
1334:             JDialog dialog =
1335:                 new ExceptionDialog(
1336:                         ProjectBrowser.getInstance(),
1337:                         "An error occured attempting to " + attemptingTo,
1338:                         ex, 
1339:                         ex instanceof OpenException);
1340:             dialog.setVisible(true);
1341:         } else {
1342:             StringWriter sw = new StringWriter();
1343:             PrintWriter pw = new PrintWriter(sw);
1344:             ex.printStackTrace(pw);
1345:             String exception = sw.toString();
1346: 
1347:             reportError(message + "\n\n" + exception, showUI);
1348:         }
1349:     }
