1389:     /**
1390:      * @see org.argouml.uml.ui.ActionSaveProject#trySave(boolean)
1391:      */
1392:     public boolean trySaveAs(boolean overwrite) {
1393:         File f = getNewFile();
1394:         if (f == null) {
1395:             return false;
1396:         }
1397: 
1398:         boolean success = ProjectBrowser.getInstance().trySave(overwrite, f);
1399:         if (success) {
1400:             ProjectBrowser.getInstance().buildTitle(
1401:                 ProjectManager.getManager().getCurrentProject().getName());
1402:         }
1403:         return success;
1404:     }
