75:     _name.setLineWidth(0);
76:     _name.setFilled(false);
77:     _name.setUnderline(true);
78: 
79:     addFig(_bigPort);
80:     addFig(_cover);
81:     addFig(_stereo);
82:     addFig(_name);
83:     addFig(_upperRect);
84:     addFig(_lowerRect);
85:   }
