87:   public FigComponentInstance(GraphModel gm, Object node) {
88:     this();
89:     setOwner(node);
90:     if (node instanceof MClassifier && (((MClassifier)node).getName() != null))
91: 	_name.setText(((MModelElement)node).getName());
92:     updateBounds();
93:   }
94: 
95:   public String placeString() {
96:     return "new ComponentInstance";
97:   }
