99:   public Object clone() {
100:     FigComponentInstance figClone = (FigComponentInstance) super.clone();
101:     Vector v = figClone.getFigs();
102:     figClone._bigPort = (FigRect) v.elementAt(0);
103:     figClone._cover = (FigRect) v.elementAt(1);
104:     figClone._stereo = (FigText) v.elementAt(2);
105:     figClone._name = (FigText) v.elementAt(3);
106:     figClone._upperRect = (FigRect) v.elementAt(4);
107:     figClone._lowerRect = (FigRect) v.elementAt(5);
108: 
109:     return figClone;
110:   }
