118:      _stereo.setFilled(false);
119:      _stereo.setLineWidth(0);
120:      _name.setFilled(false);
121:      _name.setLineWidth(0);
122:      _upperRect.setLineColor(c);
123:      _lowerRect.setLineColor(c);
124:   }
