131:   public Dimension getMinimumSize() {
132:     Dimension stereoDim = _stereo.getMinimumSize();
133:     Dimension nameDim = _name.getMinimumSize();
134: 
135:     int h = stereoDim.height + nameDim.height - OVERLAP;
136:     int w = Math.max(stereoDim.width, nameDim.width);
137:     return new Dimension(w, h);
138:   }
