140:   public void setBounds(int x, int y, int w, int h) {
141:     if (_name == null) return;
142: 
143:     Rectangle oldBounds = getBounds();
144:     _bigPort.setBounds(x, y, w, h);
145:     _cover.setBounds(x, y, w, h);
146: 
147:     Dimension stereoDim = _stereo.getMinimumSize();
148:     Dimension nameDim = _name.getMinimumSize();
149: 
150:     if (h<50) {
151:       _upperRect.setBounds(x - 10, y + h / 6, 20, 10);
152:       _lowerRect.setBounds(x - 10, y + 3*h / 6, 20, 10);
153:     }
154:     else {
155:       _upperRect.setBounds(x - 10, y + 13, 20, 10);
156:       _lowerRect.setBounds(x - 10, y + 39, 20, 10);
157:     }
158: 
159:     _stereo.setBounds(x+1, y+1, w-2, stereoDim.height);
160:     _name.setBounds(x+1, y + stereoDim.height - OVERLAP + 1, w-2, nameDim.height);
161:     _x = x; _y = y; _w = w; _h = h;
162:     firePropChange("bounds", oldBounds, getBounds());
163:     updateEdges();
164:   }
