89:      *         org.argouml.kernel.ProjectMember, java.io.Writer,
90:      *         java.lang.Integer)
91:      */
92:     public void save(ProjectMember member, Writer writer, Integer xmlFragment)
93:     	throws SaveException {
94: 
95:         ProjectMemberDiagram diagramMember = (ProjectMemberDiagram) member;
96:         OCLExpander expander;
97:         try {
98:             expander =
99:                 new OCLExpander(TemplateReader.getInstance().read(PGML_TEE));
100:         } catch (ExpansionException e) {
101:             throw new SaveException(e);
102:         }
103:         if (xmlFragment == null) {
104:             try {
105:                 expander.expand(writer, diagramMember.getDiagram());
106:             } catch (ExpansionException e) {
107:                 throw new SaveException(e);
108:             }
109:         } else {
110:             try {
111:                 File tempFile = File.createTempFile("pgml", null);
112:                 tempFile.deleteOnExit();
113:                 FileWriter w = new FileWriter(tempFile);
114:                 expander.expand(w, diagramMember.getDiagram());
115:                 w.close();
116:                 addXmlFileToWriter(
117:                         (PrintWriter) writer,
118:                         tempFile,
119:                         xmlFragment.intValue());
120:             } catch (ExpansionException e) {
121:                 throw new SaveException(e);
122:             } catch (IOException e) {
123:                 throw new SaveException(e);
124:             }
125:         }
126:     }
127: 
128: }
