556:      *      boolean, java.lang.Object, boolean, java.lang.String)
557:      */
558:     public Object buildAssociation(Object c1, boolean nav1, Object c2,
559:             boolean nav2, String name) {
560:         UmlAssociation assoc = buildAssociation((Classifier) c1, nav1,
561:                 AggregationKindEnum.AK_NONE, (Classifier) c2, nav2,
