1043:      * @see org.argouml.model.CoreFactory#buildGeneralization(java.lang.Object,
1044:      *      java.lang.Object, java.lang.String)
1045:      */
1046:     public Object buildGeneralization(Object child, Object parent, 
1047:             String name) {
1048:         if (child == null || parent == null
1049:                 || !(child instanceof GeneralizableElement)
1050:                 || !(parent instanceof GeneralizableElement)) {
1051:             throw new IllegalArgumentException();
1052:         }
1053:         Object gen = buildGeneralization(child, parent);
1054:         if (gen != null) {
