754:         // Copy attributes from our template class
755:         assoc.setNamespace(cl.getNamespace());
756:         assoc.setName(cl.getName());
757:         assoc.setAbstract(cl.isAbstract());
758:         assoc.setActive(cl.isActive());
759:         assoc.setLeaf(cl.isLeaf());
760:         assoc.setRoot(cl.isRoot());
761:         assoc.setSpecification(cl.isSpecification());
762:         assoc.getStereotype().addAll(cl.getStereotype());
763:         assoc.setVisibility(cl.getVisibility());
764:         
765:         /*
766:          * Normally we will be called with a newly created default class as our
767:          * template so only the above attribute copying is needed. The rest of
768:          * this is just in case someone wants it to be more general in the
769:          * future.
770:          * TODO: This is untested and just copies what was done in the NSUML
771:          * implementation (which is also untested for the same reason as above).
772:          */
773:         assoc.getClientDependency().addAll(cl.getClientDependency());
774:         assoc.getComment().addAll(cl.getComment());
775:         assoc.getConstraint().addAll(cl.getConstraint());        
776:         assoc.getFeature().addAll(cl.getFeature());
777:         assoc.getGeneralization().addAll(cl.getGeneralization());
778:         assoc.getPowertypeRange().addAll(cl.getPowertypeRange());
779:         assoc.getSourceFlow().addAll(cl.getSourceFlow());
