787:         //assoc.setAssociationEnds(facade.getAssociationEnds(cl));
788:         //assoc.setClassifierRoles(cl.getClassifierRole());
789:         //assoc.setClassifierRoles1(cl.getClassifierRoles1());
790:         //assoc.setClassifiersInState(cl.getClassifiersInState());
791:         //assoc.setCollaborations(cl.getCollaborations());
792:         //assoc.setCollaborations1(cl.getCollaborations1());
793:         //assoc.setCreateActions(cl.getCreateActions());
794:         //assoc.setExtensions(cl.getExtensions());
795:         //assoc.setInstances(cl.getInstances());
796:         //assoc.setObjectFlowStates(cl.getObjectFlowStates());
797:         //assoc.setParticipants(cl.getParticipants());
798:         //assoc.setPartitions1(cl.getPartitions1());
799:         //assoc.setPresentations(cl.getPresentations());
800:         //assoc.setStructuralFeatures(cl.getStructuralFeatures());
801: 
802:         buildAssociationEnd(assoc, null, end1, null, null, true, null, null,
803:                 null, null, null);
804:         buildAssociationEnd(assoc, null, end2, null, null, true, null, null,
