977:     /**
978:        Find a generalization in the model. If it does not exist, a
979:        new generalization is created.
980: 
981:        @param mPackage Look in this package.
982:        @param parent The superclass.
983:        @param child The subclass.
984:        @return The generalization found or created.
985:     */
986:     private Object getGeneralization(Object mPackage,
987:                                      Object parent,
988:                                      Object child) {
989:         String name = Model.getFacade().getName(child) + " -> "
990:             + Model.getFacade().getName(parent);
991:         Object mGeneralization = null;
992:         mGeneralization = Model.getFacade().getGeneralization(child, parent);
993:         if (mGeneralization == null) {
994:             mGeneralization =
995: 		Model.getCoreFactory().buildGeneralization(child, parent,
996: 							     name);
997:         }
998:         if (mGeneralization != null) {
999:             Model.getCoreHelper().setNamespace(mGeneralization, mPackage);
1000:         }
1001:         return mGeneralization;
