558:                 // model/classpath then information will be lost from
559:                 // source files, because the classifier cannot be
560:                 // created on the fly.
561:                 LOG.warn("Modeller.java: a classifier that was in the source"
562: 			 + " file could not be generated in the model "
563: 			 + "(to generate a generalization)- information lost",
564: 			 e);
