643:        Called from the parser when a classifier is completely parsed.
644:     */
645:     public void popClassifier() {
646:         // now create diagram if it doesn't exists in project
647: 	if (importSession != null && importSession.isCreateDiagramsChecked()) {
648: 	    if (getDiagram() == null) {
649: 		diagram = new DiagramInterface(Globals.curEditor());
650: 		if (currentPackageName != null
651: 		    && !currentPackageName.trim().equals("")) {
652: 		    // create new diagram or select existing diagram for package
653: 		    diagram.createOrSelectClassDiagram(currentPackage,
654: 							currentPackageName);
655: 		} else {
656: 		    // create new diagram in root for classifier without package
657: 		    diagram.createRootClassDiagram();
658: 		}
659: 
660: 	    } else {
661: 		if (currentPackageName != null) {
662: 		    getDiagram().selectClassDiagram(currentPackage,
663: 						    currentPackageName);
664: 		}
665: 		// the DiagramInterface is instantiated already
666: 		// but the class is in a source file
667: 		// with no package declaration
668: 		else {
669: 		    // create new diagram in root for classifier without package
670: 		    diagram.createRootClassDiagram();
671: 		}
672: 	    }
673: 	}
674:         // add the current classifier to the diagram.
675:         Object classifier = parseState.getClassifier();
676:         if (Model.getFacade().isAInterface(classifier)) {
677:             if (getDiagram() != null && importSession != null
678:                     && importSession.isCreateDiagramsChecked()) {
679: 		diagram.addInterface(classifier,
680: 				      importSession.isMinimiseFigsChecked());
681:             }
682:         } else {
683:             if (Model.getFacade().isAClass(classifier)) {
684:                 if (getDiagram() != null && importSession != null
685:                         && importSession.isCreateDiagramsChecked()) {
686:                     diagram.addClass(classifier,
687: 				      importSession.isMinimiseFigsChecked());
688:                 }
689:             }
690:         }
691: 
692:         // Remove operations and attributes not in source
693:         parseState.removeObsoleteFeatures();
694: 
695:         // Remove inner classes not in source
696:         parseState.removeObsoleteInnerClasses();
697: 
698:         parseState = (ParseState) parseStateStack.pop();
699:     }
