1004:     /**
1005:      * Find an abstraction<<realize>> in the model. If it does not
1006:      * exist, a new abstraction is created.
1007:      *
1008:      * @param parent The superclass.
1009:      * @param child The subclass.
1010:      * @return The abstraction found or created.
1011:      */
1012:     private Object getAbstraction(Object parent,
1013:                                   Object child) {
1014:         String name = Model.getFacade().getName(child) + " -> "
1015:             + Model.getFacade().getName(parent);
1016:         Object mAbstraction = null;
1017:         for (Iterator i =
1018:                 Model.getFacade().getClientDependencies(child).iterator();
1019: 	     i.hasNext();) {
1020:             mAbstraction = i.next();
1021:             Collection c = Model.getFacade().getSuppliers(mAbstraction);
1022:             if (c == null || c.size() == 0) {
1023:                 Model.getCoreHelper()
1024:                 	.removeClientDependency(child, mAbstraction);
1025:             } else {
1026:                 if (parent != c.toArray()[0]) {
1027:                     mAbstraction = null;
1028:                 } else {
1029:                     break;
1030:                 }
1031:             }
1032:         }
1033: 
1034:         if (mAbstraction == null) {
1035:             mAbstraction = Model.getCoreFactory().buildAbstraction(
1036:                    name,
1037:                    parent,
1038:                    child);
1039:         }
1040:         return mAbstraction;
1041:     }
