239:     /**
240:      * create the needed directories for the derived appropriate pathname
241:      * @return full pathname
242:      */
243:     private String generateDirectoriesPathname(Object cls, String path) {
244:         String name = Model.getFacade().getName(cls);
245:         if (name == null || name.length() == 0) {
246:             return null;
247:         }
248: 
249:         if (!path.endsWith (FILE_SEPARATOR)) {
250:             path += FILE_SEPARATOR;
251:         }
252: 
253:         String packagePath = generateRelativeDirPath(cls);
254:         String filename = name + getFileExtension();
255: 
256:         int lastIndex = -1;
257:         do {
258:             File f = new File (path);
259:             if (!f.isDirectory()) {
260:                 if (!f.mkdir()) {
261:                     LOG.error(" could not make directory " + path);
262:                     return null;
263:                 }
264:             }
265: 
266:             if (lastIndex == packagePath.length()) {
267:                 break;
268:             }
269: 
270:             int index = packagePath.indexOf (".", lastIndex + 1);
271:             if (index == -1) {
272:                 index = packagePath.length();
273:             }
274: 
275:             path += packagePath.substring(lastIndex + 1, index)
276:                 + FILE_SEPARATOR;
277:             lastIndex = index;
278:         } while (true);
279: 
280:         String pathname = path + filename;
281:         //cat.info("-----" + pathname + "-----");
282:         return pathname;
283:     }
