438:     private void writeTemplate(Object cls, String path, BufferedWriter fos) {
439:         String templatePathName = path + "/templates/";
440:         String fileName = Model.getFacade().getName(cls);
441:         String tagTemplatePathName =
442:             Model.getFacade().getTaggedValueValue(cls, "TemplatePath");
443:         String authorTag = Model.getFacade().getTaggedValueValue(cls, "author");
444:         String emailTag = Model.getFacade().getTaggedValueValue(cls, "email");
445:         if (tagTemplatePathName != null && tagTemplatePathName.length() > 0)
446:             templatePathName = tagTemplatePathName;
447:         if (generatorPass == HEADER_PASS) {
448:             templatePathName = templatePathName + "header_template";
449:             fileName = fileName + ".h";
450:         }
451:         else {
452:             templatePathName = templatePathName + "cpp_template";
453:             fileName = fileName + ".cpp";
454:         }
455:         
456:         File templateFile = new File(templatePathName);
457:         if (templateFile.exists()) {
458:             boolean eof = false;
459:             BufferedReader templateFileReader = null;
460:             try {
461:                 templateFileReader =
462:                     new BufferedReader(new FileReader(
463:                         templateFile.getAbsolutePath()));
464:                 while (!eof) {
465:                     String lineStr = templateFileReader.readLine();
466:                     if (lineStr == null) {
467:                         eof = true;
468:                     } else {
469:                         StringBuffer line = new StringBuffer(lineStr);
470:                         replaceToken(line, "|FILENAME|", fileName);
471:                         replaceToken(line, "|DATE|", getDate());
472:                         replaceToken(line, "|YEAR|", getYear());
473:                         replaceToken(line, "|AUTHOR|", authorTag);
474:                         replaceToken(line, "|EMAIL|", emailTag);
475: 
476:                         fos.write(line + LINE_SEPARATOR);
477:                     }
478:                 }
479:                 templateFileReader.close();
480:             }
481:             catch (IOException exp) { }
482:             finally {
483:                 try {
484:                     if (templateFileReader != null) templateFileReader.close();
485:                 }
486:                 catch (IOException exp) {
487:                     LOG.error("FAILED: " + templateFile.getPath());
488:                 }
489:             }
490:         }
491:     }
