493:     /**
494:      * Replace the first occurences of tokenName with tokenValue.
495:      *
496:      * @param line is the line where we do the replacing.
497:      * @param tokenName is the string we search for.
498:      * @param tokenValue is the value we replace.
499:      */
500:     private void replaceToken(StringBuffer line, String tokenName,
501:             String tokenValue) {
502:         int tokenStart;
503:         tokenStart = line.toString().indexOf(tokenName);
504:         if ((tokenStart != -1)
505:             && (tokenValue != null && tokenValue.length() > 0)) {
506:             line.replace(tokenStart,
507:                  tokenStart + tokenName.length(),
508:                  tokenValue);
509:         }
510:     }
