572:     private boolean checkInclude4UsageIndirection(boolean isIndirect,
573:             String usageTag) {
574:         boolean result = false;
575: 
576:         if ((generatorPass != HEADER_PASS)
577:             && (usageTag.indexOf("source") != -1)) {
578:             // generate include line for source .cpp pass only if
579:             // element has usage tag which specifies exclusive use in
580:             // source file
581:             result = true;
582:         } else if ((generatorPass == HEADER_PASS)
583:                && (usageTag.indexOf("source") == -1)) {
584:             // generate include line for header, if not specified as
585:             // only accessed from .cpp
586:             result = true;
587:         }
588: 
589:         // only predeclare candidates can be ignored in include block of header
590:         if ((generatorPass == HEADER_PASS) && (!isIndirect)) result = true;
591: 
592:         return result;
593:     }
