595:     private boolean checkIncludeNeeded4Element(Object cls) {
596:         String usageTag = "";
597:         boolean predeclareCandidate = false;
598: 
599:         Iterator iter = Model.getFacade().getTaggedValues(cls);
600:         while (iter.hasNext()) {
601:             Object tv = iter.next();
602:             String tag = Model.getFacade().getTagOfTag(tv);
603:             if (tag.equals("usage")) {
604:                 usageTag = Model.getFacade().getValueOfTag(tv);
605:             }
606: 
607:             if (tag.indexOf("ref") != -1 || tag.equals("&")
608:                     || tag.indexOf("pointer") != -1 || tag.equals("*")) {
609:                 predeclareCandidate = true;
610:             }
611:         }
612:         return checkInclude4UsageIndirection(predeclareCandidate, usageTag);
613:     }
