623:     private String generateHeaderDependencies(Object cls) {
624:         StringBuffer sb = new StringBuffer(160);
625:         StringBuffer predeclare = new StringBuffer(60);
626: 
627:         if (generatorPass == SOURCE_PASS) { // include header in .cpp
628:             sb.append(generateHeaderImportLine4Item(cls));
629: 
630:             Iterator iter = Model.getFacade().getTaggedValues(cls);
631:             while (iter.hasNext()) {
632:                 Object tv = iter.next();
633:                 String tag = Model.getFacade().getTagOfTag(tv);
634:                 if (tag.equals("source_incl")
635:                         || tag.equals("source_include")) {
636:                     sb.append("#include ");
637:                     sb.append(Model.getFacade().getValueOfTag(tv));
638:                     sb.append(LINE_SEPARATOR);
639:                 }
640:             }
641:         }
642:         else {
643:             Collection baseClassList = getGeneralizationClassList(
644:                     Model.getFacade().getGeneralizations(cls));
645:             sb.append(generateHeaderImportLine4ItemList(baseClassList));
646: 
647:             Iterator iter = Model.getFacade().getTaggedValues(cls);
648:             while (iter.hasNext()) {
649:                 Object tv = iter.next();
650:                 String tag = Model.getFacade().getTagOfTag(tv);
651:                 if (tag.equals("header_incl")
652:                         || tag.equals("header_include")) {
653:                     sb.append("#include ");
654:                     sb.append(Model.getFacade().getValueOfTag(tv));
655:                     sb.append(LINE_SEPARATOR);
656:                 }
657:             }
658:         }
659: 
660:         // check if the class has dependencies
661:         {
662:             Collection col = Model.getFacade().getAssociationEnds(cls);
663:             if (col != null) {
664:                 Iterator itr = col.iterator();
665:                 while (itr.hasNext()) {
666:                     Object ae = itr.next();
667:                     if (Model.getFacade().isNavigable(ae)) {
668:                         Object cls2 = Model.getFacade().getType(ae);
669:                         String name = Model.getFacade().getName(cls2);
670:                         String name2 = Model.getFacade().getName(cls);
671:                         if (name != name2) {
672:                             if (checkIncludeNeeded4Element(
673:                                     Model.getFacade().getAssociation(ae))) {
674:                                 sb.append(generateHeaderImportLine4Item(cls2));
675:                             }
676:                             else if (generatorPass == HEADER_PASS) {
677:                                 // predeclare classes which are not
678:                                 // directly used in header usefull for
679:                                 // classes which are only used
680:                                 // indirectly as pointer where no
681:                                 // knowledge about internals of class
682:                                 // are needed
683:                                 predeclare
684:                                     .append(generateHeaderPackageStart(cls2));
685:                                 predeclare
686:                                     .append("class ").append(name);
