1057:     /** 2002-11-28 Achim Spangler
1058:      * seperate generation of Operation Name from generateOperation
1059:      * so that generateOperation is language independent
1060:      * -> for C++: if we create .cpp we must prepend Owner name
1061:      *
1062:      * @param sb Where to put the result.
1063:      */
1064:     private boolean generateOperationNameAndTestForConstructor(Object op,
1065:             StringBuffer sb) {
1066:         if (generatorPass == SOURCE_PASS) {
1067:             sb.append(Model.getFacade().getName(
1068:                           Model.getFacade().getOwner(op))).append("::");
1069:         }
1070:         boolean constructor = false;
1071:         String name;
1072:         if (Model.getFacade().isConstructor(op)) {
1073:             // constructor
1074:             name = Model.getFacade().getName(Model.getFacade().getOwner(op));
1075:             constructor = true;
1076:         } else {
1077:             name = Model.getFacade().getName(op);
1078:         }
1079:         sb.append(generateName(name));
1080:         return constructor;
1081:     }
