1083:     /**
1084:      * @see org.argouml.application.api.NotationProvider2#generateOperation(
1085:      *      java.lang.Object, boolean)
1086:      *
1087:      * 2002-11-28 Achim Spangler
1088:      * modified version from Jaap Branderhorst
1089:      * -> generateOperation is language independent and seperates
1090:      *    different tasks
1091:      */
1092:     public String generateOperation(Object op, boolean documented) {
1093:         // generate nothing for abstract functions, if we generate the
1094:         // source .cpp file at the moment
1095:         if ((generatorPass == SOURCE_PASS) 
1096:                 && (Model.getFacade().isAbstract(op))) {
1097:             return "";
1098:         }
1099:         StringBuffer sb = new StringBuffer(80);
1100:         StringBuffer nameBuffer = new StringBuffer(20);
1101:         String operationIndent = (generatorPass == HEADER_PASS) ? INDENT : "";
1102:         boolean constructor =
1103:             generateOperationNameAndTestForConstructor(op, nameBuffer);
1104: 
1105:         // if generating a file always document
1106:         if (documented || generatorPass != NONE_PASS) {
1107:             // generate DocComment from tagged values
1108:             String tv = generateTaggedValues (op, DOC_COMMENT_TAGS);
1109:             if (tv != null && tv.length() > 0) {
1110:                 sb.append (LINE_SEPARATOR).append(operationIndent).append (tv);
1111:             }
1112:         }
1113: 
1114:         sb.append(operationIndent)
1115:             .append(generateOperationPrefix(op));
1116: 
1117:         // pick out return type
1118:         Object rp = Model.getCoreHelper().getReturnParameter(op);
1119:         if (!constructor) {
1120:             if (rp != null) {
1121:                 Object returnType = Model.getFacade().getType(rp);
1122:                 if (returnType == null) {
1123:                     sb.append("void ");
1124:                 }
1125:                 else if (returnType != null) {
1126:                     sb.append(generateNameWithPkgSelection(returnType))
1127:                         .append(' ');
1128:                     /* fixing 2862 - apply modifiers, 
1129:                      * i.e. pointer or reference TV */
1130:                     sb.append(generateAttributeParameterModifier(rp));
1131:                 }
1132:             }
1133:         }
1134: 
1135:         // name and params
1136:         Vector params = new Vector(Model.getFacade().getParameters(op));
1137:         params.remove(rp); // If there are several return parameters, just
1138:                            // the one found above will be removed.
1139: 
1140:         sb.append(nameBuffer.toString()).append('(');
1141: 
1142:         if (params != null) {
1143:             boolean first = true;
1144: 
1145:             for (int i = 0; i < params.size(); i++) {
1146:                 Object p = params.elementAt (i);
1147: 
1148:                 if (!first) sb.append(", ");
1149: 
1150:                 sb.append(generateParameter(p));
1151:                 first = false;
1152:             }
1153:         }
1154: 
1155:         String suffix = generateOperationSuffix(op);
1156:         if (suffix.equals(""))
1157:             sb.append(")");
1158:         else
1159:             sb.append(") ").append(suffix);
1160: 
1161:         return sb.toString();
1162:     }
