1733:         if (modifier != null && modifier.length() > 0) {
1734:             // generate: "const <type> <modifier>value"
1735:             if (modifier.equals("&")) sb.append("const ");
1736:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)))
1737:                 .append(' ').append(modifier).append("value");
