218:     private String generateRelativeDirPath(Object cls) {
219:         String packagePath = "";
220:         // avoid model being used as a package name
221:         Object parent =
222:             Model.getFacade().getNamespace(Model.getFacade().getNamespace(cls));
223:         if (parent != null) {
224:             packagePath =
225:                 Model.getFacade().getName(Model.getFacade().getNamespace(cls));
226:         }
227:         while (parent != null) {
228:             // ommit root package name; it's the model's root
229:             if (Model.getFacade().getNamespace(parent) != null) {
