810:     private String generatePackageAbsoluteName(Object pkg) {
811:         StringBuffer sb = new StringBuffer(30);
812:         String token = "";
813:         for (Object actual = pkg;
814:              actual != null;
815:              actual = getNamespaceWithoutModel(actual)) {
816:             StringTokenizer st =
817:                 new StringTokenizer(Model.getFacade().getName(actual), ".");
818:             StringBuffer tempBuf = new StringBuffer(20);
819:             while (st.hasMoreTokens()) {
820:                 token = st.nextToken();
821:                 if (tempBuf.length() > 0) tempBuf.append("::");
822:                 tempBuf.append(token);
823:             }
824:             if ((tempBuf.length() > 0) && (sb.length() > 0)) {
825:                 tempBuf.append("::");
826:             }
827:             sb.insert(0, tempBuf.toString());
828:         }
829:         return sb.toString();
