1451:     private int getVisibilityPart(Object o) {
1452:         if (Model.getFacade().isPublic(o)) {
1453:             return PUBLIC_PART;
1454:         } else if (Model.getFacade().isProtected(o)) {
1455:             return PROTECTED_PART;
1456:         } else if (Model.getFacade().isPrivate(o)) {
1457:             return PRIVATE_PART;
1458:         } else {
1459:             LOG.warn(Model.getFacade().getName(o)
1460:                     + " is not public, nor protected, "
1461:                     + "nor private!!! (ignored)");
1462:             return -1;
1463:         }
