1467:      * @see org.argouml.application.api.NotationProvider2#generateClassifier(java.lang.Object)
1468:      *
1469:      * Generates code for a classifier. In case of Java code is
1470:      * generated for classes and interfaces only at the moment.
1471:      */
1472:     public String generateClassifier(Object cls) {
1473:         if (generatorPass == NONE_PASS
1474:                 && (Model.getFacade().isAClass(cls)
1475:                     || Model.getFacade().isAInterface(cls))) {
1476:             // we're probably in the notation pane, so do a special trick
1477:             // to show both header and source
1478:             StringBuffer sb = new StringBuffer();
1479:             String name = Model.getFacade().getName(cls);
1480:             sb.append("// ").append(name).append(".h");
1481:             sb.append(LINE_SEPARATOR);
1482:             generatorPass = HEADER_PASS;
1483:             sb.append(generateClassifier(cls));
1484:             if (Model.getFacade().isAClass(cls)) {
1485:                 sb.append(LINE_SEPARATOR);
1486:                 sb.append("// ").append(name).append(".cpp");
1487:                 sb.append(LINE_SEPARATOR);
1488:                 generatorPass = SOURCE_PASS;
1489:                 sb.append(generateClassifier(cls));
1490:             }
1491:             generatorPass = NONE_PASS;
1492:             return sb.toString();
1493:         }
1494:         
1495:         StringBuffer returnValue = new StringBuffer();
1496:         StringBuffer start = generateClassifierStart(cls);
1497:         if (((start != null) && (start.length() > 0))
1498:             || (generatorPass == SOURCE_PASS)) {
1499:             StringBuffer typedefs = generateGlobalTypedefs(cls);
1500:             StringBuffer body = generateClassifierBody(cls);
1501:             StringBuffer end = generateClassifierEnd(cls);
1502:             returnValue.append((typedefs != null) ? typedefs.toString() : "");
1503:             returnValue.append(start);
1504:             if ((body != null) && (body.length() > 0)) {
1505:                 returnValue.append(LINE_SEPARATOR);
1506:                 returnValue.append(body);
1507:                 if (lfBeforeCurly) {
1508:                     returnValue.append(LINE_SEPARATOR);
1509:                 }
1510:             }
1511:             returnValue.append((end != null) ? end.toString() : "");
1512:         }
1513:         return returnValue.toString();
1514:     }
