1824:                 if (accessTag.indexOf("public") != -1) {
1825:                     generateSingleAttributeGet(attr, funcPublic);
1826:                 }
1827:                 if (accessTag.indexOf("protected") != -1) {
1828:                     generateSingleAttributeGet(attr, funcProtected);
1829:                 }
1830:                 if (accessTag.indexOf("private") != -1) {
