103:     /**
104:      * Adds a listener that listens to all modelevents that are named eventNames
105:      * and that occur to instances of a given modelClass.
106:      *
107:      * <p>
108:      * If you want the listener to be registred for remove events (that is: an
109:      * instance of the class the listener is listening too is removed), then you
110:      * have to register for the eventname "remove"
111:      * </p>
112:      * @param listener
113:      * @param modelClass
114:      * @param eventNames
115:      * @throws IllegalArgumentException if one of the arguments is null or if
116:      *  the modelClass is not a subclass of MBase.
117:      * @throws IllegalStateException if the listener is allready registred
118:      */
119:     public void addClassModelEventListener(MElementListener listener, Class modelClass, String[] eventNames) {
120:         if (listener == null || modelClass == null || eventNames == null)
121:             throw new IllegalArgumentException("Tried to add null listener to null class");
122:         if (!MBase.class.isAssignableFrom(modelClass))
123:             throw new IllegalArgumentException("Tried to add illegal class modeleventlistener.");
124:         if (eventNames.length == 0)
125:             throw new IllegalArgumentException("Tried to add an empty eventName list");
126:         for (int i = 0; i < eventNames.length; i++) {
127:             executeAddClassModelEventListener(listener, modelClass, eventNames[i]);
128:         }
129:     }
130: 
131:     /**
132:      * Convinience method to add a listener that only listens to one specific event
133:      * @param listener
134:      * @param modelClass
135:      * @param eventName
136:      */
137:     public void addClassModelEventListener(MElementListener listener, Class modelClass, String eventName) {
138:         if (listener == null || modelClass == null || eventName == null)
139:             throw new IllegalArgumentException("Tried to add null listener to null class");
140:         if (!MBase.class.isAssignableFrom(modelClass))
141:             throw new IllegalArgumentException("Tried to add illegal class modeleventlistener.");
142:         if (eventName.equals(""))
143:             throw new IllegalArgumentException("Tried to add an empty eventname");
144:         executeAddClassModelEventListener(listener, modelClass, eventName);
145:     }
