203:      * Removes a listener that listens to all modelevents fired by instances of
204:      * modelClass and that have the original name eventNames.
205:      * @param listener
206:      * @param modelClass
207:      * @param eventNames
208:      */
209:     public void removeClassModelEventListener(MElementListener listener, Class modelClass, String[] eventNames) {
210:         if (listener == null || modelClass == null || eventNames == null)
211:             throw new IllegalArgumentException("Tried to remove null listener from null class");
212:         if (!MBase.class.isAssignableFrom(modelClass))
213:             throw new IllegalArgumentException("Tried to remove illegal class modeleventlistener.");
214:         if (eventNames.length == 0)
215:             throw new IllegalArgumentException("Tried to remove an empty eventName list");
216:         for (int i = 0; i < eventNames.length; i++) {
217:             executeRemoveClassModelEventListener(listener, modelClass, eventNames[i]);
218:         }
219:     }
