221:     /**
222:      * Convinience method to remove a listener that listens to events named eventName
223:      * that are fired by instances of modelClass
224:      * @param listener
225:      * @param modelClass
226:      * @param eventName
227:      */
228:     public void removeClassModelEventListener(MElementListener listener, Class modelClass, String eventName) {
229:         if (listener == null || modelClass == null || eventName == null)
230:             throw new IllegalArgumentException("Tried to remove null listener from null class");
231:         if (!MBase.class.isAssignableFrom(modelClass))
232:             throw new IllegalArgumentException("Tried to remove illegal class modeleventlistener.");
233:         executeRemoveClassModelEventListener(listener, modelClass, eventName);
234:     }
