236:     /**
237:      * Removes a listener that listens to all modelevents fired by instances of
238:      * modelClass.
239:      * @param listener
240:      * @param modelClass
241:      * @param eventName
242:      */
243:     public void removeClassModelEventListener(MElementListener listener, Class modelClass) {
244:         if (listener == null || modelClass == null)
245:             throw new IllegalArgumentException("Tried to remove null listener from null class");
246:         if (!MBase.class.isAssignableFrom(modelClass))
