251:     private synchronized void executeRemoveClassModelEventListener(MElementListener listener, Class modelClass, String eventName) {
252:         // remove all registrations of this listener with all instances of modelClass
253:         cat.debug("Removing listener " + listener.toString() + " from modelclass " + modelClass.getName() + ". It was listening to event " + eventName);
254:         Iterator it = ModelManagementHelper.getHelper().getAllModelElementsOfKind(modelClass).iterator();
255:         while (it.hasNext()) {
256:             MBase base = (MBase)it.next();
257:             removeModelEventListener(listener, base, eventName);
258:             cat.debug("Removed the listener " + listener + " that was registred for modelelement " + base + " and event " + eventName);
259:         }
260:         // remove the listener from the registry
261:         Set listenerList = (Set) _listenerClassModelEventsMap.get(modelClass);
262:         Object[] asArray = listenerList.toArray();
263:         for (int i = 0; i < asArray.length; i++) {
264:             ListenerEventName couple = (ListenerEventName) asArray[i];
265:             if (couple.getListener() == listener && (couple.getEventName().equals(eventName) || eventName == null)) {
266:                 listenerList.remove(couple);
267:             }
268:         }
269:         if (listenerList.isEmpty()) {
270:             cat.debug("Removed the listenerlist for " + modelClass.getName() + " from the eventpump.");
271:             _listenerClassModelEventsMap.remove(modelClass);
272:         }
