191:     /**
192:      * Clone this figure.
193:      *
194:      * @return The cloned figure.
195:      */
196:     public Object clone() {
197:         FigComment figClone = (FigComment) super.clone();
198:         Iterator thisIter = this.getFigs().iterator();
199:         while (thisIter.hasNext()) {
200:             Object thisFig = thisIter.next();
201:             if (thisFig == body) {
202:                 figClone.body = (FigPoly) thisFig;
203:             }
204:             if (thisFig == urCorner) {
205:                 figClone.urCorner = (FigPoly) thisFig;
206:             }
207:             if (thisFig == text) {
208:                 figClone.text = (FigText) thisFig;
209:             }
210:         }
211:         return figClone;
212:     }
