111:     public FigComment() {
112: 
113:         body = new FigPoly(Color.black, Color.white);
114:         body.addPoint(x, y);
115:         body.addPoint(x + width - 1 - dogear, y);
116:         body.addPoint(x + width - 1, y + dogear);
117:         body.addPoint(x + width - 1, y + height - 1);
118:         body.addPoint(x, y + height - 1);
119:         body.addPoint(x, y);
120:         body.setFilled(true);
121:         body.setLineWidth(1);
122: 
123:         urCorner = new FigPoly(Color.black, Color.white);
124:         urCorner.addPoint(x + width - 1 - dogear, y);
125:         urCorner.addPoint(x + width - 1, y + dogear);
126:         urCorner.addPoint(x + width - 1 - dogear, y + dogear);
127:         urCorner.addPoint(x + width - 1 - dogear, y);
128:         urCorner.setFilled(true);
129:         Color col = body.getFillColor();
130:         urCorner.setFillColor(col.darker());
131:         urCorner.setLineWidth(1);
132: 
133:         if (SingleStereotypeEnabler.isEnabled()) {
134:             getStereotypeFig().setHeight(STEREOHEIGHT);
135:             getStereotypeFig().setVisible(false);
136:         }
137:         
138:         setBigPort(new FigRect(x, y, width, height, null, null));
139:         getBigPort().setFilled(false);
140:         getBigPort().setLineWidth(0);
141: 
142:         text = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear, height - 4, true);
143: 
144:         // add Figs to the FigNode in back-to-front order
145:         addFig(getBigPort());
146:         addFig(body);
147:         addFig(urCorner);
148:         addFig(getStereotypeFig());
149:         addFig(text);
150: 
151:         setBlinkPorts(false); //make port invisble unless mouse enters
152:         Rectangle r = getBounds();
153:         setBounds(r.x, r.y, r.width, r.height);
154:         updateEdges();
155: 
156:         readyToEdit = false;
157:         // Mark this as newly created. This is to get round the problem with
158:         // creating figs for loaded comments that had stereotypes. They are
159:         // saved with their dimensions INCLUDING the stereotype, but since we
160:         // pretend the stereotype is not visible, we add height the first time
161:         // we render such a comment. This is a complete fudge, and really we
162:         // ought to address how comment objects with stereotypes are saved. But
163:         // that will be hard work.
164:         newlyCreated = true;
165:     }
