699:     public Point getClosestPoint(Point anotherPt) {
700:         Rectangle r = getBounds();
701:         int xs[] = {r.x, r.x + r.width - dogear, r.x + r.width, 
702:                     r.x + r.width,  r.x,            r.x};
703:         int ys[] = {r.y, r.y,                    r.y + dogear,
704:                     r.y + r.height, r.y + r.height, r.y};
705:         Point p = Geometry.ptClosestTo(
706:                 xs, 
707:                 ys,
708:                 6 , anotherPt);
