500:     /**
501:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
502:      */
503:     protected void setBoundsImpl(int px, int py, int w, int h) {
504:         if (text == null) {
505:             return;
506:         }
507:         
508:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
509:         
510:         int stereotypeHeight = 0;
511:         if (getStereotypeFig().isVisible()) {
512:             if (SingleStereotypeEnabler.isEnabled()) {
513:                 stereotypeHeight = STEREOHEIGHT;
514:             } else {
515:                 stereotypeHeight = stereoMin.height;
516:             }
517:         }
518:         
519:         Rectangle oldBounds = getBounds();
520: 
521:         // Resize the text figure
522:         text.setBounds(px + 2, py + 2 + stereotypeHeight, 
523:                 w - 4 - dogear, h - 4 - stereotypeHeight);
524: 
525:         if (SingleStereotypeEnabler.isEnabled()) {
526:             getStereotypeFig().setBounds(px + 2, py + 2,
527:                     w - 4 - dogear, STEREOHEIGHT);
528:         } else {
529:             getStereotypeFig().setBounds(px + 2, py + 2,
530:                     w - 4 - dogear, stereoMin.height);
531:         }
532:         
533:         // Resize the big port around the figure
534:         getBigPort().setBounds(px, py, w, h);
535: 
536:         // Since this is a complex polygon, there's no easy way to resize it.
537:         Polygon newPoly = new Polygon();
538:         newPoly.addPoint(px, py);
539:         newPoly.addPoint(px + w - 1 - dogear, py);
540:         newPoly.addPoint(px + w - 1, py + dogear);
541:         newPoly.addPoint(px + w - 1, py + h - 1);
542:         newPoly.addPoint(px, py + h - 1);
543:         newPoly.addPoint(px, py);
544:         body.setPolygon(newPoly);
545: 
546:         // Just move the corner to it's new position.
547:         urCorner.setBounds(px + w - 1 - dogear, py, dogear, dogear);
548: 
549:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
550:         firePropChange("bounds", oldBounds, getBounds());
551:     }
