51: public class FigFinalState extends FigStateVertex {
52: 
53:     ////////////////////////////////////////////////////////////////
54:     // constants
55: 
56:     private static final int MARGIN = 2;
57:     private int x = 0;
58:     private int y = 0;
59:     private int width = 20;
60:     private int height = 20;
61: 
62:     ////////////////////////////////////////////////////////////////
63:     // instance variables
64: 
65:     private FigCircle inCircle;
66:     private FigCircle outCircle;
67: 
68:     ////////////////////////////////////////////////////////////////
69:     // constructors
70: 
71:     /**
72:      * The main constructor.
73:      */
74:     public FigFinalState() {
75:         super();
76:         Color handleColor = Globals.getPrefs().getHandleColor();
77:         x = 45;
78:         y = 0;
79:         FigRect bigPort = new FigRect(x, y, width, height);
80:         bigPort.setLineWidth(0);
81:         bigPort.setFilled(false);
82:         setBigPort(bigPort);
83:         
84:         outCircle =
85:             new FigCircle(x, y, width, height, Color.black, Color.white);
86:         inCircle =
87:             new FigCircle(
88:         		  x + 5,
89:         		  y + 5,
90:         		  width - 10,
91:         		  height - 10,
92:         		  handleColor,
93:         		  Color.black);
94:         
95:         outCircle.setLineWidth(1);
96:         inCircle.setLineWidth(0);
97:         
98:         setNameFig(new FigText(x + 10, y + 22, 0, 21, true));
99:         getNameFig().setFilled(false);
100:         getNameFig().setLineWidth(0);
101:         getNameFig().setFont(getLabelFont());
102:         getNameFig().setTextColor(Color.black);
103:         getNameFig().setMultiLine(false);
104:         getNameFig().setAllowsTab(false);
105:         getNameFig().setJustificationByName("center");
106:         	
107:         addFig(bigPort);
108:         addFig(outCircle);
109:         addFig(inCircle);
110:         addFig(getNameFig());
111:         
112:         setBlinkPorts(false); //make port invisble unless mouse enters
113:         Rectangle r = getBounds();
114:     }
