249:         _x = boundX;
250:         _y = boundY;
251:         getBigPort().setX(boundX);
252:         getBigPort().setY(boundY);
253:         outCircle.setX(boundX);
254:         outCircle.setY(boundY);
255:         inCircle.setX(boundX + 5);
256:         inCircle.setY(boundY + 5);
257:         // bigPort.setBounds(boundX, boundY, boundW, boundH);
258:         // outCircle.setBounds(boundX, boundY, boundW, boundH);
259:     }
