71:  * PopUp for extra functionality for the Explorer.
72:  *
73:  * @author alexb
74:  * @since 0.15.2
75:  */
76: public class ExplorerPopup extends JPopupMenu {
77: 
78:     private JMenu createDiagrams = new JMenu(menuLocalize("Create Diagram"));
79: 
80:     /**
81:      * Creates a new instance of ExplorerPopup.
82:      *
83:      * @param selectedItem
84:      *            is the item that we are pointing at.
85:      * @param me
86:      *            is the event.
87:      */
88:     public ExplorerPopup(Object selectedItem, MouseEvent me) {
89:         super("Explorer popup menu");
90: 
91:         /* Check if multiple items are selected. */
92:         boolean multiSelect =
93:                 TargetManager.getInstance().getTargets().size() > 1;
94: 
95:         boolean modelElementsOnly = true;
96:         for (Iterator it = TargetManager.getInstance().getTargets().iterator();
97:                 it.hasNext() && modelElementsOnly; ) {
98:             if (!Model.getFacade().isAModelElement(it.next())) {
99:         	modelElementsOnly = false;
100:             }
101:         }
102: 
103:         final Project currentProject =
104:             ProjectManager.getManager().getCurrentProject();
105:         final Diagram activeDiagram = currentProject.getActiveDiagram();
106: 
107:         // TODO: I've made some attempt to rationalize the conditions here
108:         // and make them more readable. However I'd suggest that the
109:         // conditions should move to each diagram.
110:         // Break up one complex method into a few simple ones and
111:         // give the diagrams more knowledge of themselelves
112:         // (although the diagrams may in fact delegate this in
113:         // turn to the Model component).
114:         // Bob Tarling 31 Jan 2004
115:         // eg the code here should be something like -
116:         // if (activeDiagram.canAdd(selectedItem)) {
117:         // UMLAction action =
118:         // new ActionAddExistingNode(
119:         // menuLocalize("menu.popup.add-to-diagram"),
120:         // selectedItem);
121:         // action.setEnabled(action.shouldBeEnabled());
122:         // this.add(action);
123:         // }
124: 
125:         if (!multiSelect) {
126:             initMenuCreateDiagrams();
127:             this.add(createDiagrams);
128:         }
129:         
130:         if (modelElementsOnly) {
131:             initMenuCreateModelElements();
132:         }
133: 
134:         final Object projectModel = currentProject.getModel();
135:         final boolean modelElementSelected =
136:             Model.getFacade().isAModelElement(selectedItem);
137: 
138:         if (modelElementSelected) {
139:             final boolean nAryAssociationSelected =
140:                 Model.getFacade().isANaryAssociation(selectedItem);
141:             final boolean classifierSelected =
142:                 Model.getFacade().isAClassifier(selectedItem);
143:             final boolean packageSelected =
144:                 Model.getFacade().isAPackage(selectedItem);
145:             final boolean commentSelected =
146:                 Model.getFacade().isAComment(selectedItem);
147:             final boolean stateVertexSelected =
148:                 Model.getFacade().isAStateVertex(selectedItem);
149:             final boolean instanceSelected =
150:                 Model.getFacade().isAInstance(selectedItem);
151:             final boolean dataValueSelected =
152:                 Model.getFacade().isADataValue(selectedItem);
153:             final boolean relationshipSelected =
154:                 Model.getFacade().isARelationship(selectedItem);
155:             final boolean flowSelected =
156:                 Model.getFacade().isAFlow(selectedItem);
157:             final boolean linkSelected =
158:                 Model.getFacade().isALink(selectedItem);
159:             final boolean transitionSelected =
160:                 Model.getFacade().isATransition(selectedItem);
161:             final boolean activityDiagramActive =
162:                 activeDiagram instanceof UMLActivityDiagram;
163:             final boolean sequenceDiagramActive =
164:                 activeDiagram instanceof UMLSequenceDiagram;
165:             final boolean stateDiagramActive =
166:                 activeDiagram instanceof UMLStateDiagram;
167:             final Object selectedStateMachine =
168:                 (stateVertexSelected) ? Model
169:                     .getStateMachinesHelper().getStateMachine(selectedItem)
170:                     : null;
171:             final Object diagramStateMachine =
172:                 (stateDiagramActive) ? ((UMLStateDiagram) activeDiagram)
173:                     .getStateMachine()
174:                     : null;
175:             final Object diagramActivity =
176:                 (activityDiagramActive)
177:                     ? ((UMLActivityDiagram) activeDiagram).getStateMachine()
178:                     : null;
179:                     
180:             if (!multiSelect) {
181:                 if ((classifierSelected && !relationshipSelected)
182:                         || (packageSelected && selectedItem != projectModel)
183:                         || (stateVertexSelected
184:                                 && activityDiagramActive
185:                                 && diagramActivity == selectedStateMachine)
186:                         || (stateVertexSelected
187:                                 && stateDiagramActive
188:                                 && diagramStateMachine == selectedStateMachine)
189:                         || (instanceSelected
190:                                 && !dataValueSelected
191:                                 && !sequenceDiagramActive)
192:                         || nAryAssociationSelected || commentSelected) {
193:                     Action action =
194:                         new ActionAddExistingNode(
195:                             menuLocalize("menu.popup.add-to-diagram"),
196:                             selectedItem);
197:                     this.add(action);
198:                 }
199: 
200:                 if ((relationshipSelected
201:                         && !flowSelected
202:                         && !nAryAssociationSelected)
203:                         || (linkSelected && !sequenceDiagramActive)
204:                         || transitionSelected) {
205: 
206:                     Action action =
207:                         new ActionAddExistingEdge(
208:                             menuLocalize("menu.popup.add-to-diagram"),
209:                             selectedItem);
210:                     this.add(action);
211:                     addMenuItemForBothEndsOf(selectedItem);
212:                 }
213: 
214:                 if (classifierSelected
215:                         || packageSelected) {
216:                     this.add(new ActionSetSourcePath());
217:                 }
218: 
219:                 if (Model.getFacade().isAOperation(selectedItem)) {
220:                     this.add(new ActionRESequenceDiagram());
221:                 }
222: 
223:                 if (packageSelected
224:                         || Model.getFacade().isAModel(selectedItem)) {
225:                     this.add(new ActionAddPackage());
226:                 }
227:             }
228: 
229:             if (selectedItem != projectModel) {
230:                 this.add(new ActionDeleteModelElements());
231:             }
232:         }
233:         // TODO: Make sure this shouldn't go into a previous
234:         // condition -tml
235:         if (!multiSelect) {
236:             if (selectedItem instanceof UMLClassDiagram) {
237:                 Action action =
238:                     new ActionAddAllClassesFromModel(
239:                         menuLocalize("menu.popup.add-all-classes-to-diagram"),
240:                         selectedItem);
241:                 this.add(action);
242:             }
243:         }
244: 
245:         if (multiSelect) {
246:             Collection coll = TargetManager.getInstance().getTargets();
247:             Iterator iter = (coll != null) ? coll.iterator() : null;
248:             ArrayList classifiers = new ArrayList();
249:             while (iter != null && iter.hasNext()) {
250:                 Object o = iter.next();
251:                 if (Model.getFacade().isAClassifier(o)
252:                      && !Model.getFacade().isARelationship(o)) {
253:                     classifiers.add(o);
254:                 }
255:             }
256:             if (!classifiers.isEmpty()) {
257:                 Action action =
258:                     new ActionAddExistingNodes(
259:                         menuLocalize("menu.popup.add-to-diagram"),
260:                         classifiers);
261:                 this.add(action);
262:             }
263:         }
264: 
265:         if (selectedItem instanceof Diagram) {
266:             this.add(new ActionSaveDiagramToClipboard());
267:             this.add(new ActionDeleteModelElements());
268:         }
269: 
270:     }
