358:     /**
359:      * Add popup menu items for adding to diagram both edge ends.
360:      *
361:      * @param edge
362:      *            The edge for which the menu item will be added.
363:      */
364:     private void addMenuItemForBothEndsOf(Object edge) {
365:         Collection coll = null;
366:         if (Model.getFacade().isAAssociation(edge)
367:                 || Model.getFacade().isALink(edge)) {
368:             coll = Model.getFacade().getConnections(edge);
369:         } else if (Model.getFacade().isAAbstraction(edge)
370:                 || Model.getFacade().isADependency(edge)) {
371:             coll = new ArrayList();
372:             coll.addAll(Model.getFacade().getClients(edge));
373:             coll.addAll(Model.getFacade().getSuppliers(edge));
374:         } else if (Model.getFacade().isAGeneralization(edge)) {
375:             coll = new ArrayList();
376:             Object parent = Model.getFacade().getParent(edge);
377:             coll.add(parent);
378:             coll.addAll(Model.getFacade().getChildren(parent));
379:         }
380:         if (coll == null) {
381:             return;
382:         }
383:         Iterator iter = coll.iterator();
384:         while (iter.hasNext()) {
385:             Object me = iter.next();
386:             if (me != null) {
387:                 if (Model.getFacade().isAAssociationEnd(me)) {
388:                     me = Model.getFacade().getType(me);
389:                 }
390:                 if (me != null) {
391:                     String name = Model.getFacade().getName(me);
392:                     if (name == null || name.length() == 0) {
393:                         name = "(anon element)";
394:                     }
395:                     Action action =
396:                         new ActionAddExistingRelatedNode(
397:                             menuLocalize("menu.popup.add-to-diagram") + ": "
398:                              + name,
399:                             me);
400:                     this.add(action);
401:                 }
402:             }
403:         }
404:     }
