54: public class UMLCollaborationDiagram extends UMLDiagram {
55: 
56:     /** for logging */
57:     private static final Logger LOG =
58:         Logger.getLogger(UMLCollaborationDiagram.class);
59: 
60:     ////////////////
61:     // actions for toolbar
62: 
63:     protected static Action _actionClassifierRole =
64:         new CmdCreateNode(ModelFacade.CLASSIFIER_ROLE, "ClassifierRole");
65: 
66:     protected static Action _actionAssoc =
67:         new CmdSetMode(
68:             ModeCreatePolyEdge.class,
69:             "edgeClass",
70:             ModelFacade.ASSOCIATION_ROLE,
71:             "AssociationRole");
72: 
73:     protected static Action _actionGeneralize =
74:         new CmdSetMode(
75:             ModeCreatePolyEdge.class,
76:             "edgeClass",
77:             ModelFacade.GENERALIZATION,
78:             "Generalization");
79: 
80:     protected static Action _actionAssociation =
81:         new ActionAddAssociationRole(
82:             ModelFacade.NONE_AGGREGATIONKIND,
83:             false,
84:             "Association");
85:     protected static Action _actionAggregation =
86:         new ActionAddAssociationRole(
87:             ModelFacade.AGGREGATE_AGGREGATIONKIND,
88:             false,
89:             "Aggregation");
90:     protected static Action _actionComposition =
91:         new ActionAddAssociationRole(
92:             ModelFacade.COMPOSITE_AGGREGATIONKIND,
93:             false,
94:             "Composition");
95:     protected static Action _actionUniAssociation =
96:         new ActionAddAssociationRole(
97:             ModelFacade.NONE_AGGREGATIONKIND,
98:             true,
99:             "UniAssociation");
100:     protected static Action _actionUniAggregation =
101:         new ActionAddAssociationRole(
102:             ModelFacade.AGGREGATE_AGGREGATIONKIND,
103:             true,
104:             "UniAggregation");
105:     protected static Action _actionUniComposition =
106:         new ActionAddAssociationRole(
107:             ModelFacade.COMPOSITE_AGGREGATIONKIND,
108:             true,
109:             "UniComposition");
110: 
111:     protected static Action _actionDepend =
112:         new CmdSetMode(
113:             ModeCreatePolyEdge.class,
114:             "edgeClass",
115:             ModelFacade.DEPENDENCY,
116:             "Dependency");
117: 
118:     ////////////////////////////////////////////////////////////////
119:     // contructors
120:     protected static int _CollaborationDiagramSerial = 1;
121: 
122:     public UMLCollaborationDiagram() {
123: 
124:         try {
125:             setName(getNewDiagramName());
126:         } catch (PropertyVetoException pve) { }
127:     }
128: 
129:     public UMLCollaborationDiagram(Object namespace) {
130:         this();
131:         setNamespace(namespace);
132:     }
133: 
134:     public int getNumMessages() {
135:         Layer layer = getLayer();
136:         Collection figs = layer.getContents(null);
137:         int res = 0;
138:         Iterator it = figs.iterator();
139:         while (it.hasNext()) {
140:             Fig f = (Fig) it.next();
141:             if (ModelFacade.isAMessage(f.getOwner())) {
142:                 res++;
143:             }
144:         }
145:         return res;
146:     }
147: 
148:     /** 
149:      * Method to perform a number of important initializations of a
150:      * <I>CollaborationDiagram</I>.<p>
151:      * 
152:      * Each diagram type has a similar <I>UMLxxxDiagram</I> class.<p>
153:      *
154:      * Changed <I>lay</I> from <I>LayerPerspective</I> to
155:      * <I>LayerPerspectiveMutable</I>.  This class is a child of
156:      * <I>LayerPerspective</I> and was implemented to correct some
157:      * difficulties in changing the model.  <I>Lay</I> is used mainly
158:      * in <I>LayerManager</I>(GEF) to control the adding, changing and
159:      * deleting layers on the diagram...
160:      * 
161:      * @param namespace  MNamespace from the model in NSUML...
162:      * @author psager@tigris.org Jan. 24, 2002
163:      */
164:     public void setNamespace(Object namespace) {
165:         if (!ModelFacade.isANamespace(namespace)) {
166:             cat.error(
167:                 "Illegal argument. Object " + namespace + " is not a namespace");
168:             throw new IllegalArgumentException(
169:                 "Illegal argument. Object " + namespace + " is not a namespace");
170:         }
171:         Object handle = /*(MNamespace)*/ handle;
172:         super.setNamespace(handle);
173:         CollabDiagramGraphModel gm = new CollabDiagramGraphModel();
174:         gm.setNamespace(handle);
175:         LayerPerspective lay =
176:             new LayerPerspectiveMutable(ModelFacade.getName(handle), gm);
177:         CollabDiagramRenderer rend = new CollabDiagramRenderer(); // singleton
178:         lay.setGraphNodeRenderer(rend);
179:         lay.setGraphEdgeRenderer(rend);
180:         setLayer(lay);
181: 
182:     }
183: 
184:     /**
185:      * Get the actions from which to create a toolbar or equivilent
186:      * graphic triggers
187:      */
188:     protected Object[] getUmlActions() {
189:         Object actions[] = {
190: 	    _actionClassifierRole,
191: 	    null,
192: 	    getAssociationActions(),
193: 	    ActionAddMessage.SINGLETON,
194: 	    _actionGeneralize,
195: 	    _actionDepend,
196: 	    null,
197: 	    _actionComment,
198:             _actionCommentLink};
199:         return actions;
200:     }
201: 
202:     private Object[] getAssociationActions() {
203:         Object actions[][] = {
204: 	    {_actionAssociation, _actionUniAssociation },
205: 	    {_actionAggregation, _actionUniAggregation },
206: 	    {_actionComposition, _actionUniComposition }
207:         };
208: 
209:         return actions;
210:     }
211: 
212:     /**  After loading the diagram it?s necessary to connect
213:      *  every FigMessage to its FigAssociationRole. 
214:      *  This is done by adding the FigMessage 
215:      *  to the PathItems of its FigAssociationRole */
216:     public void postLoad() {
217: 
218:         super.postLoad();
219: 
220:         Collection messages;
221:         Iterator msgIterator;
222:         if (getNamespace() == null) {
223:             cat.error("Collaboration Diagram does not belong to a namespace");
224:             return;
225:         }
226:         Collection ownedElements = ModelFacade.getOwnedElements(getNamespace());
227:         Iterator oeIterator = ownedElements.iterator();
228:         Layer lay = getLayer();
229:         while (oeIterator.hasNext()) {
230:             Object me = /*(MModelElement)*/
231: 		oeIterator.next();
232:             if (org.argouml.model.ModelFacade.isAAssociationRole(me)) {
233:                 messages = ModelFacade.getMessages(me);
234:                 msgIterator = messages.iterator();
235:                 while (msgIterator.hasNext()) {
236:                     Object message = /*(MMessage)*/
237: 			msgIterator.next();
238:                     FigMessage figMessage =
239:                         (FigMessage) lay.presentationFor(message);
240:                     if (figMessage != null) {
241:                         figMessage.addPathItemToFigAssociationRole(lay);
242:                     }
243:                 }
244:             }
245:         }
246:     }
247: 
248:     /**
249:      * Creates a new diagramname.
250:      * @return String
251:      */
252:     protected static String getNewDiagramName() {
253:         String name = null;
254:         name = "Collaboration Diagram " + _CollaborationDiagramSerial;
255:         _CollaborationDiagramSerial++;
256:         if (!ProjectManager.getManager().getCurrentProject()
257: 	        .isValidDiagramName(name)) {
258:             name = getNewDiagramName();
259:         }
260:         return name;
261:     }
262: } /* end class UMLCollaborationDiagram */
