34: /** Action to trigger creation of new collaboration diagram.
35:  *  @stereotype singleton
36:  */
37: public class ActionCollaborationDiagram extends ActionAddDiagram {
38:     
39:     private static final Logger LOG = 
40:         Logger.getLogger(ActionCollaborationDiagram.class);
41: 
42:     public static ActionCollaborationDiagram SINGLETON =
43:         new ActionCollaborationDiagram();
44: 
45:     private ActionCollaborationDiagram() {
46:         super("action.collaboration-diagram");
47:     }
48: 
49:     /**
50:      * @see org.argouml.uml.ui.ActionAddDiagram#createDiagram(Object)
51:      */
52:     public UMLDiagram createDiagram(Object handle) {
53:         if (!ModelFacade.isANamespace(handle)) {
54:             LOG.error("No namespace as argument");
55:             LOG.error(handle);
56:             throw new IllegalArgumentException(
57:                 "The argument " + handle + "is not a namespace.");
58:         }
59:         Object/*MNamespace*/ namespace = handle;
60:         Object target = TargetManager.getInstance().getTarget();
61:         Object collaboration = null;
62:         if (ModelFacade.isAOperation(target)) {
63:             collaboration =
64:                 UmlFactory.getFactory().getCollaborations().buildCollaboration(namespace);
65:             ModelFacade.setRepresentedOperation(collaboration, target);
66:         } else if (ModelFacade.isAClassifier(target)) {
67:             collaboration =
68:                 UmlFactory.getFactory().getCollaborations().buildCollaboration(target);
69:             ModelFacade.setRepresentedClassifier(collaboration, target);
70:         } else if (ModelFacade.isAModel(target)) {
71:             collaboration =
72:                 UmlFactory.getFactory().getCollaborations().buildCollaboration(target);
73:         } else if (ModelFacade.isAInteraction(target)) {
74:             collaboration = ModelFacade.getContext(target);
75:         } else if (target instanceof UMLCollaborationDiagram) {
76:             Object owner = ((UMLCollaborationDiagram) target).getOwner();
77:             if (ModelFacade.isACollaboration(owner)) {
78:                 //preventing backward compat problems
79:                 collaboration = owner;
80:             }
81:         } else if (ModelFacade.isACollaboration(target)) {
82:             collaboration = target;
83:         } else {
84:             collaboration =
85:                 UmlFactory.getFactory().getCollaborations().buildCollaboration(
86:                     namespace);
87:         }
88:         UMLCollaborationDiagram d = new UMLCollaborationDiagram(collaboration);
89:         return d;
90:     }
91: 
92:     /**
93:      * @see
94:      * org.argouml.model.uml.behavioralelements.collaborations.CollaborationsHelper#isAddingCollaborationAllowed(Object)
95:      * @see org.argouml.uml.ui.ActionAddDiagram#isValidNamespace(Object)
96:      */
97:     public boolean isValidNamespace(Object handle) {
98:         if (!ModelFacade.isANamespace(handle)) {
99:             LOG.error("No namespace as argument");
100:             LOG.error(handle);
101:             throw new IllegalArgumentException(
102:                 "The argument " + handle + "is not a namespace.");
103:         }
104:         Object/*MNamespace*/ ns = handle;
105:         return CollaborationsHelper.getHelper().isAddingCollaborationAllowed(ns);
106:     }
107: 
108:     /**
109:      * Just calls isValidNamespace(...) on the nav pane target.
110:      * @see org.argouml.uml.ui.UMLAction#shouldBeEnabled()
111:      */
112:     public boolean shouldBeEnabled() {
113: 
114:         Object target = TargetManager.getInstance().getModelTarget();
115:         if (org.argouml.model.ModelFacade.isANamespace(target))
116:             return isValidNamespace(target);
117:         else
118:             return false;
119:     }
120: 
121: } /* end class ActionCollaborationDiagram */
