26: import java.io.BufferedWriter;
27: import java.io.File;
28: import java.io.FileOutputStream;
29: import java.io.IOException;
30: import java.io.OutputStreamWriter;
31: import java.io.PrintWriter;
32: import java.net.URL;
33: import java.util.Hashtable;
34: import java.util.List;
35: 
36: import org.apache.log4j.Logger;
37: import org.argouml.application.ArgoVersion;
38: import org.argouml.kernel.Project;
39: import org.argouml.kernel.ProjectMember;
40: import org.tigris.gef.ocl.ExpansionException;
41: import org.tigris.gef.ocl.OCLExpander;
42: import org.tigris.gef.ocl.TemplateReader;
43: import org.xml.sax.SAXException;
44: 
45: /**
46:  * To persist to and from argo (xml file) storage.
47:  * 
48:  * @author Bob Tarling
49:  */
50: public class UmlFilePersister extends AbstractFilePersister {
51:     
52:     private static final Logger LOG = 
53:         Logger.getLogger(UmlFilePersister.class);
54:     
55:     private static final String ARGO_TEE = "/org/argouml/persistence/argo2.tee";
56: 
57:     /**
58:      * The constructor.
59:      *  
60:      */
61:     public UmlFilePersister() {
62:     }
63:     
64:     /**
65:      * @see org.argouml.persistence.AbstractFilePersister#getExtension()
66:      */
67:     public String getExtension() {
68:         return "uml";
69:     }
70:     
71:     /**
72:      * @see org.argouml.persistence.AbstractFilePersister#getDesc()
73:      */
74:     protected String getDesc() {
75:         return "ArgoUML project file";
76:     }
77:     
78:     /**
79:      * It is being considered to save out individual
80:      * xmi's from individuals diagrams to make
81:      * it easier to modularize the output of Argo.
82:      * 
83:      * @param file The file to write.
84:      * @param project the project to save
85:      * @throws SaveException when anything goes wrong
86:      *
87:      * @see org.argouml.persistence.ProjectFilePersister#save(
88:      * org.argouml.kernel.Project, java.io.File)
89:      */
90:     public void doSave(Project project, File file)
91:         throws SaveException {
92:         
93:         // frank: first backup the existing file to name+"#"
94:         File tempFile = new File( file.getAbsolutePath() + "#");
95:         File backupFile = new File( file.getAbsolutePath() + "~");
96:         if (tempFile.exists()) {
97:             tempFile.delete();
98:         }
99:         
100:         PrintWriter writer = null;
101:         try {
102:             if (file.exists()) {
103:                 copyFile(tempFile, file);
104:             }
105:             // frank end
106:     
107:             project.setFile(file);
108:             project.setVersion(ArgoVersion.getVersion());
109:             project.setPersistenceVersion(PERSISTENCE_VERSION);
110: 
111:             FileOutputStream stream =
112:                 new FileOutputStream(file);
113:             writer =
114:                 new PrintWriter(new BufferedWriter(new OutputStreamWriter(
115:                         stream, "UTF-8")));
116:             
117:             Integer indent = new Integer(4);
118: 
119:             writer.println("<uml version=\"" + PERSISTENCE_VERSION + "\">");
120:             // Write out header section
121:             try {
122:                 Hashtable templates = TemplateReader.getInstance()
123:                     .read(ARGO_TEE);
124:                 OCLExpander expander = new OCLExpander(templates);
125:                 expander.expand(writer, project, "  ", "");
126:                 //expander.expand(writer, project, "  "); //For next version of GEF
127:             } catch (ExpansionException e) {
128:                 throw new SaveException(e);
129:             }
130: 
131:             // Write out non xmi sections
132:             int size = project.getMembers().size();
133:             for (int i = 0; i < size; i++) {
134:                 ProjectMember projectMember = 
135:                     (ProjectMember) project.getMembers().elementAt(i);
136:                 if (projectMember.getType().equalsIgnoreCase("xmi")) {
137:                     if (LOG.isInfoEnabled()) {
138:                         LOG.info("Saving member of type: "
139:                               + ((ProjectMember) project.getMembers()
140:                                     .elementAt(i)).getType());
141:                     }
142:                     projectMember.save(writer, indent);
143:                 }
144:             }
145:             
146:             for (int i = 0; i < size; i++) {
147:                 ProjectMember projectMember = 
148:                     (ProjectMember) project.getMembers().elementAt(i);
149:                 if (!projectMember.getType().equalsIgnoreCase("xmi")) {
150:                     if (LOG.isInfoEnabled()) {
151:                         LOG.info("Saving member of type: "
152:                               + ((ProjectMember) project.getMembers()
153:                                     .elementAt(i)).getType());
154:                     }
155:                     projectMember.save(writer, indent);
156:                 }
157:             }
158:             
159:             writer.println("</uml>");
160:             
161:             writer.flush();
162:             
163:             stream.close();
164: 
165:             String path = file.getParent();
166:             if (LOG.isInfoEnabled()) {
167:                 LOG.info("Dir ==" + path);
168:             }
169:             
170:             // if save did not raise an exception 
171:             // and name+"#" exists move name+"#" to name+"~"
172:             // this is the correct backup file
173:             if (backupFile.exists()) {
174:                 backupFile.delete();
175:             }
176:             if (tempFile.exists() && !backupFile.exists()) {
177:                 tempFile.renameTo(backupFile);
178:             }
179:             if (tempFile.exists()) {
180:                 tempFile.delete();
181:             }
182:         } catch (Exception e) {
183:             LOG.error("Exception occured during save attempt", e);
184:             writer.close();
185:             
186:             // frank: in case of exception 
187:             // delete name and mv name+"#" back to name if name+"#" exists
188:             // this is the "rollback" to old file
189:             file.delete();
190:             tempFile.renameTo( file);
191:             // we have to give a message to user and set the system to unsaved!
192:             throw new SaveException(e);
193:         }
194: 
195:         writer.close();
196:     }
197:     
198:     /**
199:      * @see org.argouml.persistence.ProjectFilePersister#doLoad(java.net.URL)
200:      */
201:     public Project doLoad(URL url) throws OpenException {
202:         try {
203:             XmlInputStream inputStream =
204:                         new XmlInputStream(url.openStream(), "argo");
205: 
206:             ArgoParser parser = new ArgoParser();
207:             Project p = new Project(url);
208:             parser.readProject(p, inputStream);
209:             //inputStream.realClose();
210: 
211:             List memberList = parser.getMemberList();
212:             
213:             LOG.info(memberList.size() + " members");
214:             
215:             MemberFilePersister persister = null;
216:             for (int i = 0; i < memberList.size(); ++i) {
217:                 if (memberList.get(i).equals("pgml")) {
218:                     persister = new DiagramMemberFilePersister();
219:                 } else if (memberList.get(i).equals("todo")) {
220:                     persister = new TodoListMemberFilePersister();
221:                 } else if (memberList.get(i).equals("xmi")) {
222:                     persister = new ModelMemberFilePersister();
223:                 }
224:                 inputStream.reopen(persister.getMainTag());
225:                 persister.load(p, inputStream);
226:             }
227:             inputStream.realClose();
228:             p.postLoad();
229:             return p;
230:         } catch (IOException e) {
231:             LOG.error("IOException", e);
232:             throw new OpenException(e);
233:         } catch (SAXException e) {
234:             LOG.error("SAXException", e);
235:             throw new OpenException(e);
236:         }
237:     }
238: }
