266:     public Diagram readDiagram(InputStream is, boolean closeStream)
267:         throws SAXException {
268:         Diagram d = super.readDiagram(is, closeStream);
269:         
270:         for (int pass = 0; pass < 3; ++pass) {
271:             attachFigEdges(pass);
272:         }
273:         
274:         return d;
275:     }
276:     
277:     /**
278:      * This is called three times with the pass number incrementing
279:      * First attaching all edges except FigEdgeAssociationClass and
280:      * FigEdgeNote.
281:      * Second for FigEdgeAssociationClass only and lastly for FigEdgeNote
282:      * only.
283:      * TODO: This was hacked up rather hurredly to fix a bug.
284:      * A better implementation would be to pass through testing each
285:      * edge to see if it is possible to attach and only attaching if so.
286:      * The method should be called iteratively until all have been attached.
287:      * If an iteration results in no attachments then an error has occured.
288:      */
289:     private void attachFigEdges(int pass) throws SAXException {
290:         Iterator it = figEdges.iterator();
291:         while (it.hasNext()) {
292:             EdgeData edgeData = (EdgeData) it.next();
293:             FigEdge edge = edgeData.getEdge();
294:             
295:             boolean process = false;
296:             if (pass == 0 
297:                     && !(edge instanceof FigEdgeAssociationClass)
298:                     && !(edge instanceof FigEdgeNote)) {
299:                 process = true;
300:             } else if (pass == 1 && edge instanceof FigEdgeAssociationClass) {
301:                 process = true;
302:             } else if (pass == 2 && edge instanceof FigEdgeNote) {
303:                 process = true;
304:             }
305:             
306:             if (process) {
307:                 Object modelElement = modelElementsByFigEdge.get(edge);
308:                 if (modelElement != null) {
309:                     edge.setOwner(modelElement);
310:                 }
311:                 
312:                 Fig spf = null;
313:                 Fig dpf = null;
314:                 FigNode sfn = null;
315:                 FigNode dfn = null;
316:                 
317:                 spf = findFig(edgeData.getSourcePortFig());
318:                 dpf = findFig(edgeData.getDestPortFig());
319:                 sfn = getFigNode(edgeData.getSourceFigNode());
320:                 dfn = getFigNode(edgeData.getDestFigNode());
321:                 
322:                 if (spf == null && sfn != null) {
323:                     spf = getPortFig(sfn);
324:                 }
325: 
326:                 if (dpf == null && dfn != null) {
327:                     dpf = getPortFig(dfn);
328:                 }
329: 
330:                 if (spf == null || dpf == null || sfn == null || dfn == null) {
331:                     throw new SAXException("Can't find nodes for FigEdge: "
332:                             + edge.getId() + ":"
333:                             + edge.toString());
334:                 } else {
335:                     edge.setSourcePortFig(spf);
336:                     edge.setDestPortFig(dpf);
337:                     edge.setSourceFigNode(sfn);
338:                     edge.setDestFigNode(dfn);
339:                     edge.computeRoute();
340:                 }
341:             }
342:         }
343:     }
