205:      * and are used to show or hide the compartments within Class and Interface.
206:      * The default values are true.
207:      * @param st The StrinkTokenizer positioned at the first style identifier
208:      * @return a map of attributes
209:      */
210:     private Map interpretStyle(StringTokenizer st) {
211:         Map map = new HashMap();
212:         String name;
213:         String value;
214:         while (st.hasMoreElements()) {
215:             String namevaluepair = st.nextToken();
216:             int equalsPos = namevaluepair.indexOf('=');
217:             if (equalsPos < 0) {
218:                 name = namevaluepair;
219:                 value = "true";
220:             } else {
221:                 name = namevaluepair.substring(0, equalsPos);
222:                 value = namevaluepair.substring(equalsPos + 1);
223:             }
224: 
225:             map.put(name, value);
226:         }
227:         return map;
228:     }
229: 
230:     /**
231:      * Set the fig style attributes. This should move into
232:      * the render factories as described in issue 859.
233:      * @param fig the fig to style.
234:      * @param attributeMap a map of name value pairs
235:      */
236:     private void setStyleAttributes(Fig fig, Map attributeMap) {
237:         String name;
238:         String value;
239:         Iterator it = attributeMap.keySet().iterator();
240:         while (it.hasNext()) {
241:             name = (String) it.next();
242:             value = (String) attributeMap.get(name);
243: 
244:             if ("operationsVisible".equals(name)) {
245:                 ((OperationsCompartmentContainer) fig)
246:                     .setOperationsVisible(value.equalsIgnoreCase("true"));
247:             } else if ("attributesVisible".equals(name)) {
248:                 ((AttributesCompartmentContainer) fig)
249:                     .setAttributesVisible(value.equalsIgnoreCase("true"));
250:             } else if ("stereotypeVisible".equals(name)) {
251:                 ((StereotypeContainer) fig)
252:                     .setStereotypeVisible(value.equalsIgnoreCase("true"));
253:             } else if ("visibilityVisible".equals(name)) {
254:                 ((VisibilityContainer) fig)
255:                 .setVisibilityVisible(value.equalsIgnoreCase("true"));
256:             } else if ("pathVisible".equals(name)) {
257:                 ((PathContainer) fig)
258:                     .setPathVisible(value.equalsIgnoreCase("true"));
259:             } else if ("extensionPointVisible".equals(name)) {
260:                 ((ExtensionsCompartmentContainer) fig)
261:                     .setExtensionPointVisible(value.equalsIgnoreCase("true"));
262:             }
263:         }
264:     }
