387:     /**
388:      * Get the Fig from the FigNode that is the port.
389:      *
390:      * @param figNode the FigNode
391:      * @return the Fig that is the port on the given FigNode
392:      */
393:     private Fig getPortFig(FigNode figNode) {
394:         if (figNode instanceof FigEdgePort) {
395:             // TODO: Can we just do this every time, no need for else - Bob
396:             return figNode;
397:         } else {
398:             return (Fig) figNode.getPortFigs().get(0);
399:         }
400:     }
