272:     private void myDoubleClick(Object src) {
273: 	Object sel = null;
274: 	Diagram d = null;
275: 	if (src == resultsTable) {
276: 	    int row = resultsTable.getSelectionModel().getMinSelectionIndex();
277: 	    if (row < 0)
278: 		return;
279: 	    sel = results.elementAt(row);
280: 	    d = (Diagram) diagrams.elementAt(row);
281: 	} else if (src == relatedTable) {
282: 	    int row = relatedTable.getSelectionModel().getMinSelectionIndex();
283: 	    if (row < 0)
284: 		return;
285: 	    numJumpToRelated++;
286: 	    sel = related.elementAt(row);
287: 	}
288: 
289: 	if (d != null)
290: 	    LOG.debug("go " + sel + " in " + d.getName());
291: 	if (d != null)
292: 	    TargetManager.getInstance().setTarget(d);
293: 	TargetManager.getInstance().setTarget(sel);
294:     }
