162:      * Construct a new comment.
163:      *
164:      * @param gm the graphmodel
165:      * @param node the underlying UML Comment
166:      */
167:     public FigComment(GraphModel gm, Object node) {
168:         this();
169:         setOwner(node);
170:     }
