173:      * Get the default text for this figure.
174:      *
175:      * @return The default text for this figure.
176:      */
177:     public String placeString() {
178:         String placeString = retrieveNote();
179:         if (placeString == null) {
180:             placeString = "new note";
181:         }
182:         return placeString;
183:     }
