185:     /**
186:      * Clone this figure.
187:      *
188:      * @return The cloned figure.
189:      */
190:     public Object clone() {
191:         FigComment figClone = (FigComment) super.clone();
192:         Iterator thisIter = this.getFigs().iterator();
193:         while (thisIter.hasNext()) {
194:             Object thisFig = thisIter.next();
195:             if (thisFig == outlineFig) {
196:                 figClone.outlineFig = (FigPoly) thisFig;
197:             }
198:             if (thisFig == urCorner) {
199:                 figClone.urCorner = (FigPoly) thisFig;
200:             }
201:             if (thisFig == bodyTextFig) {
202:                 figClone.bodyTextFig = (FigText) thisFig;
203:             }
204:         }
205:         return figClone;
206:     }
