265:      */
266:     public void delayedVetoableChange(PropertyChangeEvent pce) {
267:         // update any text, colors, fonts, etc.
268:         renderingChanged();
269:         // update the relative sizes and positions of internel Figs
270:         endTrans();
271:     }
