490:     /**
491:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
492:      */
493:     protected void setBoundsImpl(int px, int py, int w, int h) {
494:         if (bodyTextFig == null) {
495:             return;
496:         }
497:         
498:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
499:         
500:         int stereotypeHeight = 0;
501:         if (getStereotypeFig().isVisible()) {
502:             stereotypeHeight = stereoMin.height;
503:         }
504:         
505:         Rectangle oldBounds = getBounds();
506: 
507:         // Resize the text figure
508:         bodyTextFig.setBounds(px + 2, py + 2 + stereotypeHeight, 
509:                 w - 4 - dogear, h - 4 - stereotypeHeight);
510: 
511:         getStereotypeFig().setBounds(px + 2, py + 2,
512:                 w - 4 - dogear, stereoMin.height);
513:         
514:         // Resize the big port around the figure
515:         getBigPort().setBounds(px, py, w, h);
516: 
517:         // Since this is a complex polygon, there's no easy way to resize it.
518:         Polygon newPoly = new Polygon();
519:         newPoly.addPoint(px, py);
520:         newPoly.addPoint(px + w - 1 - dogear, py);
521:         newPoly.addPoint(px + w - 1, py + dogear);
522:         newPoly.addPoint(px + w - 1, py + h - 1);
523:         newPoly.addPoint(px, py + h - 1);
524:         newPoly.addPoint(px, py);
525:         outlineFig.setPolygon(newPoly);
526: 
527:         // Just move the corner to it's new position.
528:         urCorner.setBounds(px + w - 1 - dogear, py, dogear, dogear);
529: 
530:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
531:         firePropChange("bounds", oldBounds, getBounds());
532:     }
