112:         outlineFig = new FigPoly(Color.black, Color.white);
113:         outlineFig.addPoint(x, y);
114:         outlineFig.addPoint(x + width - 1 - dogear, y);
115:         outlineFig.addPoint(x + width - 1, y + dogear);
116:         outlineFig.addPoint(x + width - 1, y + height - 1);
117:         outlineFig.addPoint(x, y + height - 1);
118:         outlineFig.addPoint(x, y);
119:         outlineFig.setFilled(true);
120:         outlineFig.setLineWidth(1);
121: 
122:         urCorner = new FigPoly(Color.black, Color.white);
123:         urCorner.addPoint(x + width - 1 - dogear, y);
124:         urCorner.addPoint(x + width - 1, y + dogear);
125:         urCorner.addPoint(x + width - 1 - dogear, y + dogear);
126:         urCorner.addPoint(x + width - 1 - dogear, y);
127:         urCorner.setFilled(true);
128:         Color col = outlineFig.getFillColor();
129:         urCorner.setFillColor(col.darker());
130:         urCorner.setLineWidth(1);
131: 
132:         setBigPort(new FigRect(x, y, width, height, null, null));
133:         getBigPort().setFilled(false);
134:         getBigPort().setLineWidth(0);
135: 
136:         bodyTextFig = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear, height - 4, true);
137: 
138:         // add Figs to the FigNode in back-to-front order
139:         addFig(getBigPort());
140:         addFig(outlineFig);
141:         addFig(urCorner);
142:         addFig(getStereotypeFig());
143:         addFig(bodyTextFig);
144: 
145:         setBlinkPorts(false); //make port invisble unless mouse enters
146:         Rectangle r = getBounds();
147:         setBounds(r.x, r.y, r.width, r.height);
148:         updateEdges();
149: 
150:         readyToEdit = false;
151:         // Mark this as newly created. This is to get round the problem with
152:         // creating figs for loaded comments that had stereotypes. They are
153:         // saved with their dimensions INCLUDING the stereotype, but since we
154:         // pretend the stereotype is not visible, we add height the first time
155:         // we render such a comment. This is a complete fudge, and really we
156:         // ought to address how comment objects with stereotypes are saved. But
157:         // that will be hard work.
158:         newlyCreated = true;
