547: 
548:     /**
549:      * This is called after any part of the UML ModelElement (the comment) has
550:      * changed. This method automatically updates the note FigText.
551:      *
552:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
553:      */
554:     protected final void modelChanged(PropertyChangeEvent mee) {
555:         super.modelChanged(mee);
556: 
557:         if (mee instanceof AttributeChangeEvent
558:                 && mee.getPropertyName().equals("body")) {
559:             
560:             bodyTextFig.setText(mee.getNewValue().toString());
561:             calcBounds();
562:             setBounds(getBounds());
563:             damage();
564:         }
565:     }
