60:     public void populate() {
61:         
62:         int acounter = 1;
63:         Object modelElement = getGroup().getOwner();
64:         Fig bigPort = this.getBigPort();
65:         int xpos = bigPort.getX();
66:         int ypos = bigPort.getY();
67: 
68:         List figs = getFigs();
