90:                     Notation.generate((NotationContext) getGroup(),
91:                             keyword));
92:             acounter++;
93:         }
94:         
95:         Collection stereos = Model.getFacade().getStereotypes(modelElement);
96:         if (stereos != null) {
97:             Iterator iter = stereos.iterator();
98:             while (iter.hasNext()) {
99:                 Object stereotype = iter.next();
100:                 if (figs.size() <= acounter) {
101:                     stereotypeTextFig =
102:                         new FigFeature(
103:                                 xpos + 1,
104:                                 ypos + 1
105:                                 + (acounter - 1)
106:                                 	* FigNodeModelElement.ROWHEIGHT,
107:                                 0,
108:                                 FigNodeModelElement.ROWHEIGHT - 2,
109:                                 bigPort);
110:                     // bounds not relevant here
111:                     stereotypeTextFig.setJustification(FigText.JUSTIFY_CENTER);
112:                     addFig(stereotypeTextFig);
113:                 } else {
114:                     stereotypeTextFig =
115:                         (CompartmentFigText) figs.get(acounter);
116:                 }
117:                 stereotypeTextFig.setText(
118:                         Notation.generate((NotationContext) getGroup(),
119:                         stereotype));
120:                 stereotypeTextFig.setOwner(stereotype); //TODO: update the model again here?
121:                 /* This causes another event, and modelChanged() called,
122:                  * and updateAttributes() called again...
123:                  */
124: 
125:                 acounter++;
126:             }
127:             if (figs.size() > acounter) {
128:                 //cleanup of unused FigText's
129:                 for (int i = figs.size() - 1; i >= acounter; i--) {
130:                     removeFig((Fig) figs.get(i));
131:                 }
132:             }
133:         }
134:     }
