136:     /**
137:      * Allows a parent Fig to specify some stereotype text to display that is
138:      * not actually contained by its owner.
139:      * An example of this usage is to display <<interface>> as a stereotype
140:      * on FigInterface.
141:      * @param stereotype the text of the pseudo stereotype
142:      */
143:     public void setPseudoSereotype(String stereotype) {
144:         keyword = stereotype;
145:     }
146: }
