211:      * Utility method to get the changed element from some event e
212:      * @param e
213:      * @return Object
214:      */
215:     protected Object getChangedElement(MElementEvent e) {
216:         if (e.getAddedValue() != null)
217:             return e.getAddedValue();
218:         if (e.getRemovedValue() != null)
219:             return e.getRemovedValue();
220:         if (e.getNewValue() != null)
221:             return e.getNewValue();
