996:             if (statediagram.getStateMachine() != null) {
997:                 this.moveToTrash(statediagram.getStateMachine());
998:             }
999:         }
1000:         d.removeChangeRegistryAsListener(_saveRegistry);
1001:         setNeedsSave(true);
1002:     }
