314:         // This should probably be inside xmiReader.parse
315:         // but there is another place in this source
316:         // where XMIReader is used, but it appears to be
317:         // the NSUML XMIReader.  When Argo XMIReader is used
318:         // consistently, it can be responsible for loading
319:         // the listener.  Until then, do it here.
320:         UmlHelper.getHelper().addListenersToModel(mmodel);
321: 
322:         addMember(mmodel);
