594:             currentMember = iter.next();
595:             if (currentMember instanceof ProjectMemberModel) {
596:                 Object currentModel =
597:                     ((ProjectMemberModel) currentMember).getModel();
598:                 if (currentModel == m) {
599:                     memberFound = true;
600:                     break;
601:                 }
602:             }
603:         }
604:         if (!memberFound) {
605:             if (!_models.contains(m)) {
606:                 addModel(m);
607:             }
608:             // got past the veto, add the member
609:             ProjectMember pm = new ProjectMemberModel(m, this);
610:             members.addElement(pm);
611:         }
612:     }
