328:     /**
329:      * Loads all the members from a zipped input stream.
330:      *
331:      * @param url The URL to the input stream.
332:      * @throws IOException if there is something wrong with the zipped archive
333:      *                     or with the model.
334:      * @throws ParserConfigurationException if the parser is misconfigured.
335:      * @throws SAXException if the input is not correctly formatted XML.
336:      */
337:     protected void loadZippedProjectMembers(URL url)
338:             throws IOException, ParserConfigurationException, SAXException {
339: 
340:         loadModelFromXMI(url); // throws a IOException if things go wrong
341:         // user interface has to handle that one
342:         try {
343: 
344:             // now close again, reopen and read the Diagrams.
345: 
346:             PGMLParser.SINGLETON.setOwnerRegistry(uuidRefs);
347: 
348:             //zis.close();
349:             ZipInputStream zis = new ZipInputStream(url.openStream());
350:             SubInputStream sub = new SubInputStream(zis);
351: 
352:             ZipEntry currentEntry = null;
353:             while ((currentEntry = sub.getNextEntry()) != null) {
354:                 if (currentEntry.getName().endsWith(".pgml")) {
355:                     if (LOG.isInfoEnabled()) {
356:                         LOG.info("Now going to load "
357:                                  + currentEntry.getName()
358:                                  + " from ZipInputStream");
359:                     }
360: 
361:                     // "false" means the stream shall not be closed,
362:                     // but it doesn't seem to matter...
363:                     ArgoDiagram d =
364:                         (ArgoDiagram) PGMLParser.SINGLETON.readDiagram(
365: 								      sub,
366: 								      false);
367:                     if (d != null) {                  
368:                         addMember(d);
369:                     }
370:                     else {
371:                         LOG.error("An error occurred while loading " 
372:                             + currentEntry.getName());
373:                     }
374:                     // sub.closeEntry();
375:                     if (LOG.isInfoEnabled()) {
376:                         LOG.info("Finished loading " + currentEntry.getName());
377:                     }
378:                 }
379:                 if (currentEntry.getName().endsWith(".todo")) {
380:                     ProjectMemberTodoList pm =
381:                         new ProjectMemberTodoList(currentEntry.getName(), this);
382:                     pm.load(sub);
383:                     addMember(pm);
384:                 }
385:             }
386:             zis.close();
387: 
388: 	} catch (IOException e) {
389:             ArgoParser.SINGLETON.setLastLoadStatus(false);
390:             ArgoParser.SINGLETON.setLastLoadMessage(e.toString());
391:             LOG.error("Something went wrong in " +
392: 		              "Project.loadZippedProjectMembers()", e);
393:             throw e;
394:         }
395:     }
