987:     protected void removeDiagram(ArgoDiagram d) {
988:         diagrams.removeElement(d);
989:         // if the diagram is a statechart,
990:         // remove its associated statemachine model elements
991:         if (d instanceof UMLStateDiagram) {
992:             UMLStateDiagram statediagram = (UMLStateDiagram) d;
993:             // if the statemachine has already been deleted,
994:             // and is now null,
995:             // don't attempt to delete it!
996:             if (statediagram.getStateMachine() != null) {
997:                 this.moveToTrash(statediagram.getStateMachine());
998:             }
999:         }
1000:         d.removeChangeRegistryAsListener(_saveRegistry);
1001:         setNeedsSave(true);
1002:     }
