590:     /**
591:      * Searches for a type/classifier with name s. If defineNew is
592:      * true, a new type is defined if the type/classifier is not
593:      * found. The newly created type is added to the currentNamespace
594:      * and given the name s.
595:      * @param s the name of the type/classifier to be found
596:      * @param defineNew if true, define a new one
597:      * @return MClassifier the found classifier
598:      */
599:     public Object findType(String s, boolean defineNew) {
600:         if (s != null) {
601:             s = s.trim();
602:         }
603:         if (s == null || s.length() == 0) {
604:             return null;
605:         }
606:         Object cls = null;
607:         int numModels = models.size();
608:         for (int i = 0; i < numModels; i++) {
609:             cls = findTypeInModel(s, models.elementAt(i));
610:             if (cls != null) {
611:                 return cls;
612:             }
613:         }
614:         cls = findTypeInModel(s, defaultModel);
615:         // hey, now we should move it to the model the user is working in
616:         if (cls != null) {
617:             cls =
618:                 Model.getModelManagementHelper()
619:                 	.getCorrespondingElement(cls, getRoot());
620:         }
621:         if (cls == null && defineNew) {
622:             LOG.debug("new Type defined!");
623:             cls =
624:                 Model.getCoreFactory().buildClass(getCurrentNamespace());
625:             Model.getCoreHelper().setName(cls, s);
626:         }
627:         return cls;
628:     }
