952:     /**
953:      * Removes some object from the project.
954:      *
955:      * @param obj the object to be thrown away
956:      */
957:     protected void trashInternal(Object obj) {
958:         if (Model.getFacade().isAModel(obj)) {
959:             return; //Can not delete the model
960:         }
961: 
962:         if (obj != null) {
963:             trashcan.add(obj);
964:         }
965:         if (Model.getFacade().isAModelElement(obj)) {
966: 
967:             Model.getUmlFactory().delete(obj);
968: 
969:             if (obj instanceof ProjectMember
970:                     && members.contains(obj)) {
971:                 // TODO: Bob says - can this condition ever be reached?
972:                 // Surely obj cannot be both a model element (previous if) and
973:                 // a ProjectMember (this if)
974:                 members.remove(obj);
975:             }
976: 
977:             // TODO: Presumably this is only relevant if 
978:             // obj is actually a Model.
979:             // An added test of Model.getFacade.isAModel(obj) would clarify what
980:             // is going on here.
981:             if (models.contains(obj)) {
982:                 models.remove(obj);
983:             }
984:         } else if (obj instanceof ArgoDiagram) {
985:             TargetManager.getInstance().removeTarget(obj);
986:             TargetManager.getInstance().removeHistoryElement(obj);
987:             removeProjectMemberDiagram((ArgoDiagram) obj);
988:             // only need to manually delete diagrams because they
989:             // don't have a decent event system set up.
990:             ExplorerEventAdaptor.getInstance().modelElementRemoved(obj);
991:         } else if (obj instanceof Fig) {
992:             TargetManager.getInstance().removeTarget(obj);
993:             TargetManager.getInstance().removeHistoryElement(obj);
994:             ((Fig) obj).deleteFromModel();
995:             // TODO: Bob says - I've never seen this appear in the log.
996:             // I believe this code is never reached. If we delete a FigEdge
997:             // or FigNode we actually call this method with the owner not
998:             // the Fig itself.
999:             // For Figs with no owner (primitives like circle etc) then they
1000:             // are not deleted (crtl-Del) they are removed (Del)
1001:             LOG.error("Request to delete a Fig " + obj.getClass().getName());
1002:         } else if (obj instanceof CommentEdge) {
1003:             TargetManager.getInstance().removeTarget(obj);
1004:             TargetManager.getInstance().removeHistoryElement(obj);
1005:             CommentEdge ce = (CommentEdge) obj;
1006:             LOG.info("Removing the link from " + ce.getAnnotatedElement() 
1007:                     + " to " + ce.getComment());
1008:             Model.getCoreHelper().removeAnnotatedElement(
1009:                     ce.getComment(), ce.getAnnotatedElement());
1010:         }
1011:     }
