347:     /**
348:      * @param m the member to be added
349:      */
350:     public void addMember(Object m) {
351: 
352:         if (m == null) {
353:             throw new IllegalArgumentException(
354:                     "A model member must be suppleid");
355:         } else if (m instanceof ArgoDiagram) {
356:             LOG.info("Adding diagram member");
357:             addDiagramMember((ArgoDiagram) m);
358:         } else if (m instanceof ProjectMemberTodoList) {
359:             LOG.info("Adding todo member");
360:             addTodoMember((ProjectMemberTodoList) m);
361:         } else if (Model.getFacade().isAModel(m)) {
362:             LOG.info("Adding model member");
363:             addModelMember(m);
364:         } else {
365:             throw new IllegalArgumentException(
366:                     "The member must be a UML model todo member or diagram."
367:                     + "It is " + m.getClass().getName());
368:         }
369:         LOG.info("There are now " + members.size() + " members");
370:     }
