688: 
689:         Collection allClassifiers =
690:             Model.getModelManagementHelper()
691: 	        .getAllModelElementsOfKind(ns,
692: 	                Model.getMetaTypes().getClassifier());
693: 
694:         Object[] classifiers = allClassifiers.toArray();
695:         Object classifier = null;
696: 
697:         for (int i = 0; i < classifiers.length; i++) {
698: 
699:             classifier = classifiers[i];
700:             if (Model.getFacade().getName(classifier) != null
701:             		&& Model.getFacade().getName(classifier).equals(s)) {
702:                 return classifier;
703:             }
704:         }
705: 
706:         return null;
707:     }
