372:     /**
373:      * @param m the model
374:      */
375:     private void addModelMember(Object m) {
376: 
377:         boolean memberFound = false;
378:         Object currentMember =
379:             members.getMember(ProjectMemberModel.class);
380:         if (currentMember != null) {
381:             Object currentModel =
382:                 ((ProjectMemberModel) currentMember).getModel();
383:             if (currentModel == m) {
384:                 memberFound = true;
385:             }
386:         }
387: 
388:         if (!memberFound) {
389:             if (!models.contains(m)) {
390:                 addModel(m);
391:             }
392:             // got past the veto, add the member
393:             ProjectMember pm = new ProjectMemberModel(m, this);
394:             LOG.info("Adding model member to start of member list");
395:             members.add(pm);
396:         } else {
397:             LOG.info("Attempted to load 2 models");
398:             throw new IllegalArgumentException(
399:                     "Attempted to load 2 models");
400:         }
401:     }
