403:     /**
404:      * @param model a namespace
405:      */
406:     public void addModel(Object model) {
407: 
408:         if (!Model.getFacade().isANamespace(model)) {
409:             throw new IllegalArgumentException();
410: 	}
411: 
412:         // fire indeterminate change to avoid copying vector
413:         if (!models.contains(model)) {
414:             models.addElement(model);
415:         }
416:         setCurrentNamespace(model);
417:         ProjectManager.getManager().setSaveEnabled(true);
418:     }
