177:     /**
178:      * Override default JTree implementation to display the
179:      * appropriate text for any object that will be displayed in
180:      * the Nav pane.
181:      *
182:      * @see javax.swing.JTree#convertValueToText(java.lang.Object,
183:      * boolean, boolean, boolean, int, boolean)
184:      */
185:     public String convertValueToText(Object value,
186: 				     boolean selected,
187: 				     boolean expanded,
188: 				     boolean leaf,
189: 				     int row,
190: 				     boolean hasFocus) {
191: 
192:         // do model elements first
193:         if (Model.getFacade().isAModelElement(value)) {
194: 
195:             String name = null;
196: 
197:             // Jeremy Bennett patch
198:             if (Model.getFacade().isATransition(value)
199: 		    || Model.getFacade().isAExtensionPoint(value)) {
200:                 name = GeneratorDisplay.getInstance().generate(value);
201:             }
202:             /* Changing the label in case of comments.
203:              * This is necessary in UML 1.3 since the name of the comment 
204:              * is the same as the content of the comment (called "body" 
205:              * in UML 1.4), causing the total comment to be
206:              * displayed in the perspective */
207:             else if (Model.getFacade().isAComment(value)) {
208:                 name = Model.getFacade().getName(value);
209: 
210:                 if (name != null
211: 		    && name.indexOf("\n") < 80
212: 		    && name.indexOf("\n") > -1) {
213: 
214:                     name = name.substring(0, name.indexOf("\n")) + "...";
215:                 }
216:                 else if (name != null && name.length() > 80) {
217:                     name = name.substring(0, 80) + "...";
218:                 }
219:             } else {
220:                 name = Model.getFacade().getName(value);
221:             }
222: 
223:             if (name == null || name.equals("")) {
224:                 name = 
225:                     "(anon " + Model.getFacade().getUMLClassName(value) + ")";
226:             }
227: 
228:             // Look for stereotype
229:             if (showStereotype) {
230:                 Object stereo = null;
231:                 if (Model.getFacade().getStereotypes(value).size() > 0) {
232:                     stereo = Model.getFacade().getStereotypes(value)
233:                         .iterator().next();
234:                 }
235:                 if (stereo != null) {
236:                     name += " " + GeneratorDisplay.getInstance()
237:                         .generate(stereo);
238:                 }
239:             }
240: 
241:             return name;
242:         }
243: 
244:         if (Model.getFacade().isATaggedValue(value)) {
245:             String tagName = Model.getFacade().getTagOfTag(value);
246:             if (tagName == null || tagName.equals(""))
247:                 tagName = "(anon)";
248:             return ("1-" + tagName);
249:         }
250: 
251:         if (value instanceof Diagram) {
252:             return ((Diagram) value).getName();
253:         }
254:         if (value != null)
255:             return value.toString();
256:         return "-";
257:     }
