363:       guard = s.substring(s.indexOf("[", 0)+1, s.indexOf("]")).trim();
364:       s = s.substring(0, s.indexOf("[")) + s.substring(s.indexOf("]")+1);
365:       s = s.trim();
366:     }
367: 
368:     if (s.indexOf("/", 0) > -1) {
369:       actions = s.substring(s.indexOf("/")+1).trim();
370:       s = s.substring(0, s.indexOf("/")).trim();
371:     }
372: 
373:     trigger = s;
374: 
375: //     System.out.println("name=|" + name +"|");
