54:     java.util.StringTokenizer st = new java.util.StringTokenizer(s, "\n\r");
55:     List newOps = new ArrayList();
56:     while (st.hasMoreTokens()) {
57:       String token = st.nextToken();
58:       MOperation op = parseOperation(token);
59:       newOps.add(op);
60:     }
61:     // System.out.println("parsed " + newOps.size() + " operations");
62: 	Vector features = new Vector(cls.getFeatures());
63: 	Vector oldOps = new Vector(MMUtil.SINGLETON.getOperations(cls));
