164:   public String parseOutKeywords(MFeature f, String s) {
165:     s = s.trim();
166:     int firstSpace = s.indexOf(" ");
167:     if (firstSpace == -1) return s;
168:     String visStr = s.substring(0, firstSpace);
169: 
170:       if (visStr.equals("static"))
171: 	f.setOwnerScope(MScopeKind.CLASSIFIER);
172:       else if (visStr.equals("synchronized") && (f instanceof MOperation))
173: 	((MOperation)f).setConcurrency(MCallConcurrencyKind.GUARDED);
174:       else if (visStr.equals("transient"))
175: 	System.out.println("'transient' keyword is currently ignored");
176:       else if (visStr.equals("final"))
177: 	System.out.println("'final' keyword is currently ignored");
178:       else if (visStr.equals("abstract"))
179: 	System.out.println("'abstract' keyword is currently ignored");
180:       else {
181: 	return s;
182:       }
183: 
184:     return parseOutKeywords(f, s.substring(firstSpace+1));
185:   }
