483:       name = s.substring(0, s.indexOf(":")).trim();
484:       basefirst = s.substring(s.indexOf(":") + 1).trim();
485:       if (basefirst.indexOf(":", 0) > 1) {
486:         base = basefirst.substring(0, basefirst.indexOf(":")).trim();
487:       }
488:       else base = basefirst;
489:     }
490:     else {
491:       name = s;
492:     }
493: 
494:     Collection col = obj.getClassifiers();
495:     if ((col != null) && (col.size()>0)) { 
496:       Iterator itcol = col.iterator(); 
497:       while (itcol.hasNext()) { 
498:         MClassifier cls = (MClassifier) itcol.next(); 
499:         obj.removeClassifier(cls); 
500:       } 
501:     } 
502: 
503:     Vector diagrams = ProjectBrowser.TheInstance.getProject().getDiagrams();
504:     Vector v = new Vector();
505:     MClass classifier = new MClassImpl();
506:     GraphModel model = null;
