471:   /** Parse a line of the form: "name: base-class" */
472:   public void parseObject(MObject obj, String s) {
473:     // strip any trailing semi-colons
474:     s = s.trim();
475:     if (s.length() == 0) return;
476:     if (s.charAt(s.length()-1) == ';')
477:       s = s.substring(0, s.length() - 2);
478: 
479:     String name = "";
480:     String bases = "";
481:     String base = "";
482:     if (s.indexOf(":", 0) > -1) {
483:       name = s.substring(0, s.indexOf(":")).trim();
484:       bases = s.substring(s.indexOf(":") + 1).trim();
485:       if (bases.indexOf(":", 0) > 1) {
486:         base = bases.substring(0, bases.indexOf(":")).trim();
487:       }
488:       else base = bases;
489:     }
490:     else {
491:       name = s;
492:     }
493: 
494:     Collection col = obj.getClassifiers();
495:     if ((col != null) && (col.size()>0)) { 
496:       Iterator itcol = col.iterator(); 
497:       while (itcol.hasNext()) { 
498:         MClassifier cls = (MClassifier) itcol.next(); 
499:         obj.removeClassifier(cls); 
500:       } 
501:     } 
502: 
503:     Vector diagrams = ProjectBrowser.TheInstance.getProject().getDiagrams();
504:     Vector v = new Vector();
505:     MClass classifier = new MClassImpl();
506:     GraphModel model = null;
507:     int size = diagrams.size();
508:     for (int i=0; i<size; i++) {
509:       Object o = diagrams.elementAt(i);
510:       if (!(o instanceof Diagram)) continue;
511:       if (o instanceof MModel) continue;
512:       Diagram d = (Diagram) o;
513:       model = d.getGraphModel(); 
514:       if (!(model instanceof ClassDiagramGraphModel || model instanceof DeploymentDiagramGraphModel)) continue;
515:        
516:       Vector nodes = model.getNodes();
517:       int si = nodes.size();
518:       for (int j=0; j<si; j++) {
519:         MModelElement node = (MModelElement) nodes.elementAt(j);
520:         if (node != null && (node instanceof MClassImpl)) {
521:           MClass mclass = (MClass) node;
522:           if (mclass.getNamespace() != obj.getNamespace()) continue;
523:           String class_name = mclass.getName();
524:           if (class_name != null && (class_name.equals(base))) {
525:             v.addElement(mclass);
526:             obj.setClassifiers(v);
527:             obj.setName(new String(name)); 
528:             return; 
529:           }      
530:         }
531:       }
532:     }
533:     classifier.setName(base);
534:     
535:     v.addElement(classifier);
536:     obj.setClassifiers(v);
537:     obj.setName(new String(name));
538: 
539:   }
