1009:      * with the index in the array + start
1010:      */
1011:     void contractNodes(int start, boolean[] emptyNodes) {
1012:         int contracted = 0;
1013:         for (int i = 0; i < emptyNodes.length; ++i) {
1014:             if (emptyNodes[i]) {
1015:                 if (((MessageNode) linkPositions.get(i + start - contracted))
1016: 		        .getFigMessagePort()
1017: 		    != null) {
1018:                     throw new IllegalArgumentException(
1019: 		    	"Trying to contract non-empty MessageNode");
1020: 		}
1021:                 linkPositions.remove(i + start - contracted);
1022:                 ++contracted;
1023:             }
1024:         }
1025:         if (contracted > 0) {
1026:             updateNodeStates();
1027:             Rectangle r = getBounds();
1028:             r.height -= contracted * SequenceDiagramLayout.LINK_DISTANCE;
1029:             updateEdges();
1030:             setBounds(r);
1031:         }
