389:     public void assertEntrySetAgainstArrays(Set entrySet, Object[] keyArray, Object[] valueArray) {
390:         // Check that the set returned by keySet() contains all the items in the
391:         // keys array
392:         int count = 0;
393:         Iterator it = entrySet.iterator();
394:         while (it.hasNext()) {
395:             Map.Entry entry = (Map.Entry) it.next();
396:             Object key = entry.getKey();
397:             Object value = entry.getValue();
398:             assertEquals(keyArray[count], key);
399:             assertEquals(valueArray[count], value);
400:             count++;
401:         }
402:         assertEquals(keyArray.length , count);
403:         assertEquals(valueArray.length , count);
404:     }
