379:     private void assertIteratorAgainstArray(Iterator it, Object[] array) {
380:         int count = 0;
381:         while (it.hasNext()) {
382:             Object o = it.next();
383:             assertEquals(array[count], o);
384:             count++;
385:         }
386:         assertEquals(array.length , count);
