46: /**
47:  * The fig for a link in a sequence diagram.
48:  *
49:  * @author jaap.branderhorst@xs4all.nl
50:  */
51: public abstract class FigMessage
52:     extends FigEdgeModelElement {
53: 
54:     private FigTextGroup textGroup;
55: 
56:     /**
57:      * Contructs a new figlink and sets the owner of the figlink.
58:      *
59:      * @param owner is the owner.
60:      */
61:     public FigMessage(Object owner) {
62:         super();
63:         textGroup = new FigTextGroup();
64:         textGroup.addFig(getNameFig());
65:         textGroup.addFig(getStereotypeFig());
66:         addPathItem(textGroup, new PathConvPercent(this, 50, 10));
67:         setOwner(owner);
68:     }
69: 
70:     /**
71:      * Constructor here for saving and loading purposes.
72:      *
73:      */
74:     public FigMessage() {
75:         this(null);
76:     }
77: 
78:     /**
79:      * Build a collection of menu items relevant for a right-click
80:      * popup menu on a message.
81:      *
82:      * @param     me     a mouse event
83:      * @return           a collection of menu items
84:      *
85:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
86:      */
87:     public Vector getPopUpActions(MouseEvent me) {
88:         Vector popUpActions = super.getPopUpActions(me);
89:         
90:         // the menu item for RE a sequence into the diagram is offered always,
91:         // becauase some check (does a operation with a body exist) would be
92:         // too expensive
93:         popUpActions.insertElementAt(new ActionRESequenceDiagram(this),
94:                 popUpActions.size() - getPopupAddOffset());
95:         
96:         return popUpActions;
97:     }
98: 
99:     /**
100:      * Returns the action attached to this link if any.<p>
101:      *
102:      * @return the action attached to this link or null if there isn't any.
103:      */
104:     public Object getAction() {
105:         Object owner = getOwner();
106:         if (owner != null && Model.getFacade().isAMessage(owner)) {
107:             return Model.getFacade().getAction(owner);
108:         }
109:         return null;
110:     }
111: 
112:     /**
113:      * @see org.tigris.gef.presentation.Fig#setOwner(java.lang.Object)
114:      */
115:     public void setOwner(Object newOwner) {
116:         super.setOwner(newOwner);
117:         if (Model.getFacade().isAMessage(newOwner)) {
118:             Model.getPump().addModelEventListener(this, newOwner, "name");
119:         }
120:     }
121: 
122:     /**
123:      * @see org.tigris.gef.presentation.FigEdge#getSourcePortFig
124:      */
125:     public Fig getSourcePortFig() {
126:         Fig result = super.getSourcePortFig();
127:         if (result instanceof FigClassifierRole.TempFig
128: 	    && getOwner() != null) {
129: 	    result =
130: 		getSourceFigClassifierRole().createFigMessagePort(getOwner(),
131: 							       result);
132:             setSourcePortFig(result);
133:         }
134:         return result;
135:     }
136: 
137:     /**
138:      * @see org.tigris.gef.presentation.FigEdge#getDestPortFig
139:      */
140:     public Fig getDestPortFig() {
141:         Fig result = super.getDestPortFig();
142:         if (result instanceof FigClassifierRole.TempFig
143: 	    && getOwner() != null) {
144: 	    result =
145: 		getDestFigClassifierRole().createFigMessagePort(getOwner(),
146: 								result);
147:             setDestPortFig(result);
148:         }
149:         return result;
150:     }
151: 
152:     /**
153:      * Computes the route of this {@link FigMessage} and computes the
154:      * connectionpoints of the figlink to the ports.  This depends on
155:      * the action attached to the owner of the {@link FigMessage}.  Also
156:      * adds FigActivations etc or moves the {@link FigClassifierRole}s
157:      * if necessary.<p>
158:      *
159:      * @see org.tigris.gef.presentation.FigEdge#computeRoute()
160:      */
161:     public void computeRoute() {
162:         Fig sourceFig = getSourcePortFig();
163:         Fig destFig = getDestPortFig();
164:         if (sourceFig != null && destFig != null) {
165:             Point startPoint = sourceFig.connectionPoint(destFig.getCenter());
166:             Point endPoint = destFig.connectionPoint(sourceFig.getCenter());
167:             if (sourceFig instanceof FigMessagePort
168: 		&& destFig instanceof FigMessagePort) {
169:                 FigMessagePort srcMP = (FigMessagePort) sourceFig;
170:                 FigMessagePort destMP = (FigMessagePort) destFig;
171:                 // If it is a self-message
172:                 if (srcMP.getNode().getFigClassifierRole()
173: 		    == destMP.getNode().getFigClassifierRole()) {
174:                     if (startPoint.x < sourceFig.getCenter().x) {
175:                         startPoint.x += sourceFig.getWidth();
176: 		    }
177:                     endPoint.x = startPoint.x;
178:                     setEndPoints(startPoint, endPoint);
179:                     // If this is the first time it is laid out, will only
180:                     // have 2 points, add the middle point
181:                     if (getNumPoints() <= 2) {
182:                         insertPoint(0, startPoint.x
183: 				    + SequenceDiagramLayout.OBJECT_DISTANCE / 3,
184:                                     (startPoint.y + endPoint.y) / 2);
185:                     } else {
186: 			// Otherwise, move the middle point
187:                         int middleX =
188: 			    startPoint.x
189: 			    + SequenceDiagramLayout.OBJECT_DISTANCE / 3;
190:                         int middleY = (startPoint.y + endPoint.y) / 2;
191:                         Point p = getPoint(1);
192:                         if (p.x != middleX || p.y != middleY) {
193: 			    setPoint(new Handle(1), middleX, middleY);
194:                         }
195:                     }
196:                 } else {
197:                     setEndPoints(startPoint, endPoint);
198: 		}
199:             } else {
200:                 setEndPoints(startPoint, endPoint);
201: 	    }
202:             calcBounds();
203:             layoutEdge();
204:         }
205:     }
206: 
207:     public MessageNode getSourceMessageNode() {
208:         return ((FigMessagePort) getSourcePortFig()).getNode();
209:     }
210: 
211:     public MessageNode getDestinationMessageNode() {
212:         return ((FigMessagePort) getDestPortFig()).getNode();
213:     }
214: 
215:     /**
216:      * Returns the message belonging to this link if there is one
217:      * (otherwise null).<p>
218:      *
219:      * @return the message.
220:      */
221:     public Object getMessage() {
222:     	return getOwner();
223:     }
224: 
225:     /**
226:      * @see org.tigris.gef.presentation.FigEdgePoly#layoutEdge()
227:      */
228:     protected void layoutEdge() {
229:         if (getSourcePortFig() instanceof FigMessagePort
230: 	    && getDestPortFig() instanceof FigMessagePort) {
231:             if (((FigMessagePort) getSourcePortFig()).getNode() != null
232: 		&& ((FigMessagePort) getDestPortFig()).getNode() != null) {
233:                 ((SequenceDiagramLayout) getLayer()).updateActivations();
234:                 Globals.curEditor().damageAll();
235:             }
236:         }
237:     }
238: 
239:     /**
240:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#getSource()
241:      */
242:     protected Object getSource() {
243:         Object owner = getOwner();
244:         if (owner == null) {
245:             return null;
246: 	}
247:         return Model.getFacade().getSender(owner);
248:     }
249: 
250:     /**
251:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#getDestination()
252:      */
253:     protected Object getDestination() {
254:         Object owner = getOwner();
255:         if (owner == null) {
256:             return null;
257: 	}
258: 
259:         return Model.getFacade().getReceiver(owner);
260:     }
261: 
262:     /**
263:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#modelChanged(java.beans.PropertyChangeEvent)
264:      */
265:     public void modelChanged(PropertyChangeEvent pce) {
266:         super.modelChanged(pce);
267:         textGroup.calcBounds();
268:     }
269: 
270:     /**
271:      * @return the source figobject
272:      */
273:     public FigClassifierRole getSourceFigClassifierRole() {
274:         return (FigClassifierRole) getSourceFigNode();
275:     }
276: 
277:     /**
278:      * @return the destination fig object
279:      */
280:     public FigClassifierRole getDestFigClassifierRole() {
281:         return (FigClassifierRole) getDestFigNode();
282:     }
283: 
284:     /**
285:      * This won't work, so this implementation does nothing.
286:      *
287:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#updateClassifiers
288:      */
289:     protected boolean updateClassifiers() {
290:         return true;
291:     }
292: 
293:     /**
294:      * @see org.tigris.gef.presentation.Fig#makeSelection()
295:      */
296:     public Selection makeSelection() {
297:         return new SelectionMessage(this);
298:     }
299: }
