45: /**
46:  * Mode to create a link between two figobjects. This mode extends
47:  * ModeCreate and not ModeCreateEdge because ModeCreateEdge hides its
48:  * variables a bit too much...
49:  *
50:  * @author jaap.branderhorst@xs4all.nl
51:  */
52: public class ModeCreateMessage extends ModeCreate {
53: 
54:     private static final Logger LOG =
55: 	Logger.getLogger(ModeCreateMessage.class);
56: 
57:     /**
58:      * The NetPort where the arc is paintn from.
59:      */
60:     private Object startPort;
61: 
62:     /**
63:      * The Fig that presents the starting NetPort.
64:      */
65:     private Fig startPortFig;
66: 
67:     /**
68:      * The FigNode on the NetNode that owns the start port.
69:      */
70:     private FigNode sourceFigClassifierRole;
71: 
72:     /**
73:      * The new NetEdge that is being created.
74:      */
75:     private Object newEdge;
76: 
77:     /**
78:      * The constructor.
79:      *
80:      */
81:     public ModeCreateMessage() {
82:         super();
83:     }
84: 
85:     /**
86:      * The constructor.
87:      *
88:      * @param par the editor
89:      */
90:     public ModeCreateMessage(Editor par) {
91:         super(par);
92:     }
93: 
94:     /**
95:      * @see org.tigris.gef.base.ModeCreate#createNewItem(
96:      * java.awt.event.MouseEvent, int, int)
97:      */
98:     public Fig createNewItem(MouseEvent me, int snapX, int snapY) {
99:         return new FigLine(
100:             snapX,
101:             snapY,
102:             me.getX(),
103:             snapY,
104:             Globals.getPrefs().getRubberbandColor());
105:     }
106: 
107:     /**
108:      * @see org.tigris.gef.base.FigModifyingMode#instructions()
109:      */
110:     public String instructions() {
111:         return Translator.localize("action.sequence.new."
112: 				   + getArg("actionName"));
113:     }
114: 
115:     /**
116:      * On mousePressed determine what port the user is dragging from.
117:      * The mousePressed event is sent via ModeSelect.
118:      *
119:      * @see java.awt.event.MouseListener#mousePressed(java.awt.event.MouseEvent)
120:      */
121:     public void mousePressed(MouseEvent me) {
122:         if (me.isConsumed()) {
123:             return;
124: 	}
125:         int x = me.getX(), y = me.getY();
126:         Editor ce = Globals.curEditor();
127:         Fig underMouse = ce.hit(x, y);
128:         if (underMouse == null) {
129:             underMouse = ce.hit(x - 16, y - 16, 32, 32);
130:         }
131:         if (underMouse == null) {
132:             done();
133:             me.consume();
134:             return;
135:         }
136:         if (!(underMouse instanceof FigNode)) {
137:             done();
138:             me.consume();
139:             return;
140:         }
141:         sourceFigClassifierRole = (FigNode) underMouse;
142:         startPort = sourceFigClassifierRole.deepHitPort(x, y);
143:         if (startPort == null) {
144:             done();
145:             me.consume();
146:             return;
147:         }
148:         startPortFig = sourceFigClassifierRole.getPortFig(startPort);
149:         start();
150:         Point snapPt = new Point();
151:         synchronized (snapPt) {
152:             snapPt.setLocation(
153:                 startPortFig.getX() + FigClassifierRole.WIDTH / 2,
154:                 startPortFig.getY());
155:             editor.snap(snapPt);
156:             anchorX = snapPt.x;
157:             anchorY = snapPt.y;
158:         }
159:         _newItem = createNewItem(me, anchorX, anchorY);
160:         me.consume();
