173:     private void updateFigPositions() {
174:     	Collection figs = getFigs(); // the figs that make up this group
175:         Iterator it = figs.iterator();
176:     	if (!figs.isEmpty()) {
177:             FigMessage previousFig = null;
178:             for (int i = 0; it.hasNext(); i++) {
179:                 FigMessage fig = (FigMessage) it.next();
180:                 int y;
181:                 if (i != 0) {
182:                     y = previousFig.getY() + previousFig.getHeight() + 5;
183:                 } else {
184:                     y = getY();
185:                 }
186:                 fig.setLocation(getX(), y);
187:                 fig.endTrans();
188:                 previousFig = fig;
189:             }
