42: /**
43:  * This class represents the Fig of an AssociationRole
44:  * for a collaboration diagram.
45:  *
46:  */
47: public class FigAssociationRole extends FigAssociation {
48: 
49:     /**
50:      * Serial version - Eclipse generated for rev. 1.30
51:      */
52:     private static final long serialVersionUID = -6543020797101620194L;
53:     
54:     private FigMessageGroup messages = new FigMessageGroup();
55: 
56:     /**
57:      * Main Constructor
58:      */
59:     public FigAssociationRole() {
60: 	super(); // this really is questionable
61: 	addPathItem(messages, new PathConvPercent(this, 50, 10));
62:     }
63: 
64:     /**
65:      * Constructor for FigAssociationRole.
66:      * @param edge the owning UML element
67:      * @param lay the layer
68:      */
69:     public FigAssociationRole(Object edge, Layer lay) {
70: 	this();
71: 	setLayer(lay);
72:     	setOwner(edge);
73:     }
74: 
75:     /**
76:      * Create the NotationProviders.
77:      * 
78:      * @param own the current owner
79:      */
80:     protected void initNotationProviders(Object own) {
81:         if (Model.getFacade().isAAssociationRole(own)) {
82:             if (Model.getFacade().isAAssociation(own)) {
83:                 Object[] ends = 
84:                     Model.getFacade().getConnections(own).toArray(); 
85:                 Object ae0 = ends[0];
86:                 Object ae1 = ends[1];
87:                 notationProviderSrcRole =
88:                     NotationProviderFactory2.getInstance().getNotationProvider(
89:                             NotationProviderFactory2.TYPE_ASSOCIATION_END_NAME, 
90:                             ae0);
91:                 notationProviderDestRole =
92:                     NotationProviderFactory2.getInstance().getNotationProvider(
93:                             NotationProviderFactory2.TYPE_ASSOCIATION_END_NAME, 
94:                             ae1);
95:             }
96:             notationProviderName =
97:                 NotationProviderFactory2.getInstance().getNotationProvider(
98:                         NotationProviderFactory2.TYPE_ASSOCIATION_ROLE, 
99:                         own);
100:         }
101:     }
102: 
103:     /**
104:      * @see org.argouml.uml.diagram.ui.FigAssociation#updateListeners(
105:      * java.lang.Object)
106:      */
107:     public void updateListeners(Object newOwner) {
108:         super.updateListeners(newOwner);
109:         if (newOwner != null) {
110:             /* Also listen to the base: */
111:             Object assoc = Model.getFacade().getBase(newOwner);
112:             if (assoc != null) {
113:                 addElementListener(assoc);
114:             }
115:         }
116:     }
117: 
118:     /**
119:      * @param message the message to be added
120:      */
121:     public void addMessage(FigMessage message) {
122:     	messages.addFig(message);
123:     	updatePathItemLocations();
124:     	messages.damage();
125:     }
126: 
127:     /**
128:      * @see org.tigris.gef.presentation.Fig#removeFromDiagram()
129:      */
130:     public void removeFromDiagramImpl() {
131:         super.removeFromDiagramImpl();
132:         messages.removeFromDiagram();
133:     }
134:     
135:     /**
136:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#textEditStarted(org.tigris.gef.presentation.FigText)
137:      */
138:     protected void textEditStarted(FigText ft) {
139:         if (ft == getNameFig()) {
140:             showHelp(notationProviderName.getParsingHelp());
141:         }
142:     }
143: 
144: } /* end class FigAssociationRole */
