763:     /**
764:      * Handles changes of the model. Takes into account the event that
765:      * occured. If you need to update the whole fig, consider using
766:      * renderingChanged.<p>
767:      *
768:      * @see FigNodeModelElement#modelChanged(MElementEvent)
769:      */
770:     protected void modelChanged(MElementEvent mee) {
771:         super.modelChanged(mee);
772: 
773:         if (getOwner() == null) {
774:             return;
775:         }
776: 
777:         // attributes
778:         if (mee == null
779:                 || ModelFacade.isAAttribute(mee.getSource())
780:                 || (mee.getSource() == getOwner()
781: 		&& mee.getName().equals("feature"))) {
782:             updateAttributes();
783:             damage();
784:         }
785:         // operations
786:         if (mee == null
787:                 || ModelFacade.isAOperation(mee.getSource())
788:                 || ModelFacade.isAParameter(mee.getSource())
789:                 || (mee.getSource() == getOwner()
790: 		&& mee.getName().equals("feature"))) {
791:             updateOperations();
792:             damage();
793:         }
794:         if (mee != null && mee.getName().equals("parameter") 
795:                 && ModelFacade.isAOperation(mee.getSource())) {
796:             if (mee.getAddedValue() != null) {
797:                 UmlModelEventPump.getPump().addModelEventListener(this, 
798:                         mee.getAddedValue(), new String[] {
799:                             "name", "kind", "type", "defaultValue"});
800:             }
801:             if (mee.getRemovedValue() != null) {
802:                 UmlModelEventPump.getPump().addModelEventListener(this, 
803:                         mee.getRemovedValue());
804:             }
805:         }
806:         if (mee == null || mee.getName().equals("isAbstract")) {
807:             updateAbstract();
808:             damage();
809:         }
810:         if (mee == null || mee.getName().equals("stereotype")) {
811:             updateStereotypeText();
812:             updateAttributes();
813:             updateOperations();
814:             damage();
815:         }
816:         if (mee != null && ModelFacade.getStereotypes(getOwner())
817:                                 .contains(mee.getSource())) {
818:             updateStereotypeText();
819:             damage();
820:         }
821:         // name updating
822:         super.modelChanged(mee);
823:     }
