1093:             // TODO: in future version of GEF call getFigs returning array
1094:             Vector figs = new Vector(getAttributesFig().getFigs(null));
1095:             CompartmentFigText attr;
1096:             while (iter.hasNext()) {
1097:                 Object sf = /*(MStructuralFeature)*/ iter.next();
1098:                 // update the listeners
1099: 		// UmlModelEventPump.getPump().removeModelEventListener(this,
1100: 		// sf);
1101:                 UmlModelEventPump.getPump().addModelEventListener(this, sf);
1102:                 if (figs.size() <= acounter) {
1103:                     attr =
1104: 			new FigFeature(xpos + 1,
1105: 				       ypos + 1 + (acounter - 1) * ROWHEIGHT,
1106: 				       0,
1107: 				       ROWHEIGHT - 2,
1108: 				       attrPort);
1109:                     // bounds not relevant here
