1116:                     getAttributesFig().addFig(attr);
1117:                 } else {
1118:                     attr = (CompartmentFigText) figs.elementAt(acounter);
1119:                 }
1120:                 attr.setText(Notation.generate(this, sf));
1121:                 attr.setOwner(sf);
1122:                 // underline, if static
1123:                 attr.setUnderline(ModelFacade.CLASSIFIER_SCOPEKIND
1124: 				  .equals(ModelFacade.getOwnerScope(sf)));
1125:                 acounter++;
1126:             }
1127:             if (figs.size() > acounter) {
1128:                 //cleanup of unused attribute FigText's
1129:                 for (int i = figs.size() - 1; i >= acounter; i--) {
1130:                     getAttributesFig().removeFig((Fig) figs.elementAt(i));
1131:                 }
1132:             }
1133:         }
1134:         Rectangle rect = getBounds();
1135:         updateFigGroupSize(getAttributesFig(), xpos, ypos, 0, 0);
1136:         // ouch ugly but that's for a next refactoring
1137:         // TODO: make setBounds, calcBounds and updateBounds consistent
