1083:     protected void updateAttributes() {
1084:         Object cls = /*(MClassifier)*/ getOwner();
1085:         Fig attrPort = ((FigAttributesCompartment) getFigAt(ATTRIBUTES_POSN))
1086:             .getBigPort();
1087:         int xpos = attrPort.getX();
1088:         int ypos = attrPort.getY();
1089:         int acounter = 1;
1090:         Collection strs = ModelFacade.getStructuralFeatures(cls);
1091:         if (strs != null) {
1092:             Iterator iter = strs.iterator();
1093:             // TODO: in future version of GEF call getFigs returning array
