299:             showMenu.add(ActionCompartmentDisplay.showAttrCompartment());
300:         }
301:         if (isOperationsVisible()) {
302:             showMenu.add(ActionCompartmentDisplay.hideOperCompartment());
303:         } else {
304:             showMenu.add(ActionCompartmentDisplay.showOperCompartment());
305:         }
306:         showMenu.add(ActionEdgesDisplay.getShowEdges());
307:         showMenu.add(ActionEdgesDisplay.getHideEdges());
308:         popUpActions.insertElementAt(showMenu,
309:             popUpActions.size() - POPUP_ADD_OFFSET);
310: 
311:         // Modifiers ...
312:         popUpActions.insertElementAt(
313:                 buildModifierPopUp(ABSTRACT | LEAF | ROOT | ACTIVE),
314:                 popUpActions.size() - POPUP_ADD_OFFSET);
