880:     /**
881:      * <p>Sets the bounds, but the size will be at least the one returned by
882:      *   {@link #getMinimumSize()}, unless checking of size is disabled.</p>
883:      *
884:      * <p>If the required height is bigger, then the additional height is
885:      *   equally distributed among all figs (i.e. compartments), such that the
886:      *   cumulated height of all visible figs equals the demanded height<p>.
887:      *
888:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
889:      *   a knowledge that the minimum height of a name compartment is 21
890:      *   pixels.</p>
891:      *
892:      * @param x  Desired X coordinate of upper left corner
893:      *
894:      * @param y  Desired Y coordinate of upper left corner
895:      *
896:      * @param w  Desired width of the FigClass
897:      *
898:      * @param h  Desired height of the FigClass
899:      */
900:     public void setBounds(int x, int y, int w, int h) {
901: 
902:         // Save our old boundaries (needed later), and get minimum size
903:         // info. "aSize will be used to maintain a running calculation of our
904:         // size at various points.
905: 
906:         // "extra_each" is the extra height per displayed fig if requested
907:         // height is greater than minimal. "height_correction" is the height
908:         // correction due to rounded division result, will be added to the name
909:         // compartment
910: 
911:         Rectangle oldBounds = getBounds();
912:         Dimension aSize = 
913:             isCheckSize() ? getMinimumSize() : new Dimension(w, h);
914: 
915:         int newW = Math.max(w, aSize.width);
916:         int newH = h;
917: 
918:         int extraEach = 0;
919:         int heightCorrection = 0;
920: 
921:         // First compute all nessessary height data. Easy if we want less than
922:         // the minimum
923: 
924:         if (newH <= aSize.height) {
925: 
926:             // Just use the mimimum
927: 
928:             newH = aSize.height;
929: 
930:         } else {
931: 
932:             // Split the extra amongst the number of displayed compartments
933: 
934:             int displayedFigs = 1; //this is for getNameFig()
935: 
936:             if (getAttributesFig().isVisible()) {
937:                 displayedFigs++;
938:             }
939: 
940:             if (isOperationsVisible()) {
941:                 displayedFigs++;
942:             }
943: 
944:             // Calculate how much each, plus a correction to put in the name
945:             // comparment if the result is rounded
946: 
947:             extraEach = (newH - aSize.height) / displayedFigs;
948:             heightCorrection =
949: 		(newH - aSize.height) - (extraEach * displayedFigs);
950:         }
951: 
952:         // Now resize all sub-figs, including not displayed figs. Start by the
953:         // name. We override the getMinimumSize if it is less than our view (21
954:         // pixels hardcoded!). Add in the shared extra, plus in this case the
955:         // correction.
956: 
957:         int height = getNameFig().getMinimumSize().height;
958: 
959:         if (height < 21) {
960:             height = 21;
961:         }
962: 
963:         height += extraEach + heightCorrection;
964: 
965:         // Now sort out the stereotype display. If the stereotype is displayed,
966:         // move the upper boundary of the name compartment up and set new
967:         // bounds for the name and the stereotype compatments and the
968:         // stereoLineBlinder that blanks out the line between the two
969: 
970:         int currentY = y;
971: 
972:         if (getStereotypeFig().isVisible()) {
973:             currentY += STEREOHEIGHT;
974:         }
975: 
976:         getNameFig().setBounds(x, currentY, newW, height);
977:         getStereotypeFig().setBounds(x, y, newW, STEREOHEIGHT + 1);
978:         getFigAt(BLINDER_POSN).setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
979: 
980:         // Advance currentY to where the start of the attribute box is,
981:         // remembering that it overlaps the next box by 1 pixel. Calculate the
982:         // size of the attribute box, and update the Y pointer past it if it is
983:         // displayed.
984: 
985:         currentY += height - 1; // -1 for 1 pixel overlap
986: 
987:         int na = (isAttributesVisible())
988:     	    ? Math.max(1, getAttributesFig().getFigs(null).size() - 1)
989:     	    : 0;
990:         int no = (isOperationsVisible())
991:     	    ? Math.max(1, getOperationsFig().getFigs(null).size() - 1)
992:     	    : 0;
993:         if (isCheckSize()) {
994:             height = ROWHEIGHT * na + 2 + extraEach;
995:         } else if (newH > currentY - y && na + no > 0) {
996:             height = (newH + y - currentY) * na / (na + no) + 1;
997:         } else {
998:             height = 1;
999:         }
1000:         aSize = updateFigGroupSize(getAttributesFig(), x, currentY, 
1001:                 newW, height);
1002: 
1003:         if (getAttributesFig().isVisible()) {
1004:             currentY += aSize.height - 1; // -1 for 1 pixel overlap
1005:         }
1006: 
1007:         // Finally update the bounds of the operations box
1008: 
1009:         aSize =
1010: 	    updateFigGroupSize(getOperationsFig(), x, currentY, 
1011:                 newW, newH + y - currentY);
1012: 
1013:         // set bounds of big box
1014: 
1015:         getBigPort().setBounds(x, y, newW, newH);
1016: 
1017:         // Now force calculation of the bounds of the figure, update the edges
1018:         // and trigger anyone who's listening to see if the "bounds" property
1019:         // has changed.
1020: 
1021:         calcBounds();
1022:         updateEdges();
1023:         firePropChange("bounds", oldBounds, getBounds());
1024:     }
