1275: 			    .removeModelEventListener(this, param);
1276:                     }
1277:                 }
1278:             }
1279:         }
1280:         if (newOwner != null) { // add the listeners to the newOwner
1281:             Object cl = /*(MClass)*/ newOwner;
1282:             Iterator it = ModelFacade.getFeatures(cl).iterator();
1283:             while (it.hasNext()) {
1284:                 Object feat = /*(MFeature)*/ it.next();
1285:                 if (ModelFacade.isAOperation(feat)) {
