1290:                         // UmlModelEventPump.getPump()
1291:                         // .removeModelEventListener(this, param);
1292:                         UmlModelEventPump.getPump()
1293: 			    .addModelEventListener(this, param);
1294:                     }
1295:                 }
1296:             }
1297:         }
1298: 
1299:         super.updateListeners(newOwner);
