676:     /**
677:      * @param fgVec the FigGroup
678:      * @param ft    the Figtext
679:      * @param i     get the fig after fig i
680:      * @return the FigText
681:      */
682:     protected FigText getNextVisibleFeature(FigGroup fgVec, FigText ft, int i)
683:     {
684:         if (fgVec == null || i < 1) {
685:             return null;
686:         }
687:         FigText ft2 = null;
688:         // TODO: come GEF V 0.12 use getFigs returning an array
689:         Vector v = new Vector(fgVec.getFigs(null));
690:         if (i >= v.size() || !((FigText) v.elementAt(i)).isVisible()) {
691:             return null;
692:         }
693:         do {
694:             i++;
695:             while (i >= v.size()) {
696:                 fgVec = (fgVec == getAttributesFig()) 
697:                     ? getOperationsFig() 
698:                     : getAttributesFig();
699:                 v = new Vector(fgVec.getFigs(null));
