1113:                     attr.setTextColor(Color.black);
1114:                     attr.setJustification(FigText.JUSTIFY_LEFT);
1115:                     attr.setMultiLine(false);
1116:                     getAttributesFig().addFig(attr);
1117:                 } else {
1118:                     attr = (CompartmentFigText) attributeFigs.elementAt(acounter);
