1078:     /**
1079:      * Updates the attributes in the fig. Called from modelchanged if there is
1080:      * a modelevent effecting the attributes and from renderingChanged in all
1081:      * cases.
1082:      */
1083:     protected void updateAttributes() {
1084:         Object cls = /*(MClassifier)*/ getOwner();
1085:         Fig attrPort = ((FigAttributesCompartment) getFigAt(ATTRIBUTES_POSN))
1086:             .getBigPort();
1087:         int xpos = attrPort.getX();
1088:         int ypos = attrPort.getY();
1089:         int acounter = 1;
1090:         Collection strs = ModelFacade.getStructuralFeatures(cls);
1091:         if (strs != null) {
1092:             Iterator iter = strs.iterator();
1093:             // TODO: in future version of GEF call getFigs returning array
1094:             Vector attributeFigs = new Vector(getAttributesFig().getFigs(null));
1095:             CompartmentFigText attr;
1096:             while (iter.hasNext()) {
1097:                 Object sf = /*(MStructuralFeature)*/ iter.next();
1098:                 // update the listeners
1099: 		// UmlModelEventPump.getPump().removeModelEventListener(this,
1100: 		// sf);
1101:                 UmlModelEventPump.getPump().addModelEventListener(this, sf);
1102:                 if (attributeFigs.size() <= acounter) {
1103:                     attr =
1104: 			new FigFeature(xpos + 1,
1105: 				       ypos + 1 + (acounter - 1) * ROWHEIGHT,
1106: 				       0,
1107: 				       ROWHEIGHT - 2,
1108: 				       attrPort);
1109:                     // bounds not relevant here
1110:                     attr.setFilled(false);
