42: /**
43:  * Class to display graphics for a UML ActionState in a diagram.
44:  *
45:  * @author ics 125b silverbullet team
46:  */
47: public class FigActionState extends FigStateVertex {
48: 
49:     ////////////////////////////////////////////////////////////////
50:     // constants
51: 
52:     private static final int MARGIN = 2;
53: 
54:     private static final int PADDING = 8;
55: 
56:     ////////////////////////////////////////////////////////////////
57:     // instance variables
58: 
59:     private FigRRect cover;
60: 
61:     ////////////////////////////////////////////////////////////////
62:     // constructors
63: 
64:     /**
65:      * Constructor FigActionState
66:      */
67:     public FigActionState() {
68:         setBigPort(new FigRRect(10 + 1, 10 + 1, 90 - 2, 25 - 2, Color.cyan,
69:                 Color.cyan));
70:         ((FigRRect) getBigPort()).setCornerRadius(getBigPort().getHalfHeight());
71:         cover = new FigRRect(10, 10, 90, 25, Color.black, Color.white);
72:         cover.setCornerRadius(getHalfHeight());
73: 
74:         getBigPort().setLineWidth(0);
75:         getNameFig().setLineWidth(0);
76:         getNameFig().setBounds(10 + PADDING, 10, 90 - PADDING * 2, 25);
77:         getNameFig().setFilled(false);
78:         getNameFig().setMultiLine(true);
79: 
80:         // add Figs to the FigNode in back-to-front order
81:         addFig(getBigPort());
82:         addFig(cover);
83:         addFig(getNameFig());
84: 
85:         //setBlinkPorts(false); //make port invisble unless mouse enters
86:         Rectangle r = getBounds();
87:         setBounds(r.x, r.y, r.width, r.height);
88:     }
89: 
90:     /**
91:      * Constructor FigActionState
92:      * @param gm ignored!
93:      * @param node owner
94:      */
95:     public FigActionState(GraphModel gm, Object node) {
96:         this();
97:         setOwner(node);
98:     }
99: 
100:     /**
101:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#placeString()
102:      */
103:     public String placeString() {
104:         return "new ActionState";
105:     }
106: 
107:     /**
108:      * @see java.lang.Object#clone()
109:      */
110:     public Object clone() {
111:         FigActionState figClone = (FigActionState) super.clone();
112:         Iterator it = figClone.getFigs().iterator();
113:         figClone.setBigPort((FigRRect) it.next());
114:         figClone.cover = (FigRRect) it.next();
115:         figClone.setNameFig((FigText) it.next());
116:         return figClone;
117:     }
118: 
119:     ////////////////////////////////////////////////////////////////
120:     // Fig accessors
121: 
122:     /**
123:      * @see org.tigris.gef.presentation.Fig#getMinimumSize()
124:      */
125:     public Dimension getMinimumSize() {
126:         Dimension nameDim = getNameFig().getMinimumSize();
127:         int w = nameDim.width + PADDING * 2;
128:         int h = nameDim.height + PADDING;
129:         return new Dimension(w, h);
130:     }
131: 
132:     /**
133:      * Override setBounds to keep shapes looking right
134:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
135:      */
136:     public void setBounds(int x, int y, int w, int h) {
137:         if (getNameFig() == null) return;
138:         Rectangle oldBounds = getBounds();
139: 
140:         getNameFig().setBounds(x + PADDING, y, w - PADDING * 2, h - PADDING);
141:         getBigPort().setBounds(x + 1, y + 1, w - 2, h - 2);
142:         cover.setBounds(x, y, w, h);
143:         ((FigRRect) getBigPort()).setCornerRadius(h);
144:         cover.setCornerRadius(h);
145: 
146:         calcBounds();
147:         updateEdges();
148:         firePropChange("bounds", oldBounds, getBounds());
149:     }
150: 
151:     /**
152:      * @see org.tigris.gef.presentation.Fig#setLineColor(java.awt.Color)
153:      */
154:     public void setLineColor(Color col) {
155:         cover.setLineColor(col);
156:     }
157: 
158:     /**
159:      * @see org.tigris.gef.presentation.Fig#getLineColor()
160:      */
161:     public Color getLineColor() {
162:         return cover.getLineColor();
163:     }
164: 
165:     /**
166:      * @see org.tigris.gef.presentation.Fig#setFillColor(java.awt.Color)
167:      */
168:     public void setFillColor(Color col) {
169:         cover.setFillColor(col);
170:     }
171: 
172:     /**
173:      * @see org.tigris.gef.presentation.Fig#getFillColor()
174:      */
175:     public Color getFillColor() {
176:         return cover.getFillColor();
177:     }
178: 
179:     /**
180:      * @see org.tigris.gef.presentation.Fig#setFilled(boolean)
181:      */
182:     public void setFilled(boolean f) {
183:         cover.setFilled(f);
184:     }
185: 
186:     /**
187:      * @see org.tigris.gef.presentation.Fig#getFilled()
188:      */
189:     public boolean getFilled() {
190:         return cover.getFilled();
191:     }
192: 
193:     /**
194:      * @see org.tigris.gef.presentation.Fig#setLineWidth(int)
195:      */
196:     public void setLineWidth(int w) {
197:         cover.setLineWidth(w);
198:     }
199: 
200:     /**
201:      * @see org.tigris.gef.presentation.Fig#getLineWidth()
202:      */
203:     public int getLineWidth() {
204:         return cover.getLineWidth();
205:     }
206: 
207:     /**
208:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
209:      */
210:     protected void modelChanged(PropertyChangeEvent mee) {
211:         super.modelChanged(mee);
212:         if (mee.getSource() == getOwner()
213:                 && mee.getPropertyName().equals("entry")) {
214:             if (mee.getNewValue() != null) {
215:                 Model.getPump().addModelEventListener(this,
216:                                             mee.getNewValue(), "script");
217:             } else
218:                 if (mee.getOldValue() != null) {
219:                     Model.getPump().removeModelEventListener(this,
220:                                             mee.getOldValue(), "script");
221:                 }
222:             updateNameText();
223:             damage();
224:         } else
225:             if (Model.getFacade().getEntry(getOwner()) == mee.getSource()) {
226:                 updateNameText();
227:                 damage();
228:             }
229: 
230:     }
231: 
232: 
233:     /**
234:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
235:      */
236:     protected void updateNameText() {
237:         if (getOwner() != null)
238:             getNameFig().setText(Notation.generate(this, getOwner()));
239:     }
240: 
241: 
242:     /**
243:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEdited(org.tigris.gef.presentation.FigText)
244:      */
245:     protected void textEdited(FigText ft) throws PropertyVetoException {
246:         if (ft == getNameFig() && this.getOwner() != null) {
247:             ParserDisplay.SINGLETON.parseActionState(ft.getText(),
248:                     this.getOwner());
249:         } else
250:             super.textEdited(ft);
251:     }
252: } /* end class FigActionState */
