140:     public static final Object COLLABORATION    = MCollaboration.class;
141:     public static final Object DEPENDENCY       = MDependency.class;
142:     public static final Object EXTEND           = MExtend.class;
143:     public static final Object GENERALIZATION   = MGeneralization.class;
144:     public static final Object INCLUDE          = MInclude.class;
145:     public static final Object LINK             = MLink.class;
146:     public static final Object PERMISSION       = MPermission.class;
147:     public static final Object USAGE            = MUsage.class;
148:     public static final Object TRANSITION       = MTransition.class;
