887:     /** Recognizer for primary objects.
888:      * A primary object is an object that is created by the parser or
889:      * by a user.
890:      * Object that are created when importing some other object are not.
891:      *
892:      * @param handle candidate
893:      * @returns true if primary object.
894:      */
895:     public static boolean isPrimaryObject(Object handle) {
896:         if (handle instanceof MModelElement) {
897:             MModelElement element = (MModelElement) handle;
898:             for (Iterator i = element.getTaggedValues().iterator(); 
899: 		 i.hasNext();
900: 		 ) {
901:                 MTaggedValue tv = (MTaggedValue) i.next();
902:                 if ((MMUtil.GENERATED_TAG).equals(tv.getTag())) {
903:                     return false;
904:                 }
905:             }
906:             return true;
907:         }
908:         // ...
909:         throw new IllegalArgumentException("Unrecognized object " + handle);
910:     }
