1025:     /**
1026:      * Returns the association end between some classifier and some associaton.
1027:      * @param type
1028:      * @param assoc
1029:      * @return association end
1030:      */
1031:     public static Object getAssociationEnd(Object type, Object assoc) {
1032:         if (type == null
1033:             || assoc == null
1034:             || !(type instanceof MClassifier)
1035:             || !(assoc instanceof MAssociation))
1036:             return null;
1037:         Iterator it = ((MClassifier) type).getAssociationEnds().iterator();
1038:         while (it.hasNext()) {
1039:             MAssociationEnd end = (MAssociationEnd) it.next();
1040:             if (((MAssociation) assoc).getConnections().contains(end))
1041:                 return end;
1042:         }
1043:         return null;
1044:     }
