274:     /**
275:      * Return actions available for building toolbar or similar.
276:      * @return an array of available actions.
277:      */
278:     public Object[] getActions() {
279:         Object manipulateActions[] = getManipulateActions();
280:         Object umlActions[] = getUmlActions();
281:         Object shapeActions[] = getShapeActions();
282: 
283:         Object actions[] =
284:             new Object[manipulateActions.length
285:                 + umlActions.length
286:                 + shapeActions.length];
287: 
288:         int posn = 0;
289:         System.arraycopy(
290:             manipulateActions,
291:             0,
292:             actions,
293:             posn,
294:             manipulateActions.length);
295:         posn += manipulateActions.length;
296:         System.arraycopy(umlActions, 0, actions, posn, umlActions.length);
297:         posn += umlActions.length;
298:         System.arraycopy(shapeActions, 0, actions, posn, shapeActions.length);
299: 
300:         return actions;
301:     }
