354:             ProjectManager.getManager().getCurrentProject().getDiagrams().get(
355:                 0);
356:         TargetManager.getInstance().setTarget(newTarget);
357:         UmlModelEventPump.getPump().removeModelEventListener(
358:             this,
359:             namespace,
360:             UmlModelEventPump.REMOVE);
361:         ProjectManager.getManager().getCurrentProject().moveToTrash(this);
362: 
363:     }
