494:         for (int i = 0; i < toolCount; ++i) {
495:             Component c = toolBar.getComponent(i);
496:             if (c instanceof ToolButton) {
497:                 ToolButton tb = (ToolButton) c;
498:                 Action action = tb.getRealAction();
499:                 if (action instanceof RadioAction) {
500:                     action = ((RadioAction) action).getAction();
501:                 }
502:                 tb.setSelected(false);
503:                 ButtonModel bm = tb.getModel();
504:                 bm.setRollover(false);
505:                 bm.setSelected(false);
506:                 bm.setArmed(false);
507:                 bm.setPressed(false);
508:                 tb.setBorderPainted(false);
509:             }
510:         }
511:     }
