622: class ActionRemoveFromModel extends UMLChangeAction {
623:   public ActionRemoveFromModel() { super("Remove From Model"); }
624:   public boolean shouldBeEnabled() {
625:     ProjectBrowser pb = ProjectBrowser.TheInstance;
626:     Object target = pb.getDetailsTarget();
627:     if (target instanceof ModelElement) return true;
628: 
629:     // needs-more-work: trashing diagrams
630:     Editor ce = Globals.curEditor();
631:     Vector figs = ce.getSelectionManager().getFigs();
632:     int size = figs.size();
633:     for (int i = 0; i < size; i++) {
634:       Fig f = (Fig) figs.elementAt(i);
635:       Object owner = f.getOwner();
636:       if (owner instanceof ModelElement) return true;
637:     }
638:     return false;
639:   }
640:   public void actionPerformed(ActionEvent ae) {
641:     ProjectBrowser pb = ProjectBrowser.TheInstance;
642:     Object target = pb.getDetailsTarget();
643:     Project p = pb.getProject();
644:     if (target instanceof ModelElement)
645:       p.moveToTrash(target);
646:     // needs-more-work: trashing diagrams
647:     else {
648:       Editor ce = Globals.curEditor();
649:       Vector figs = ce.getSelectionManager().getFigs();
650:       int size = figs.size();
651:       for (int i = 0; i < size; i++) {
652: 	Fig f = (Fig) figs.elementAt(i);
653: 	Object owner = f.getOwner();
654: 	if (owner instanceof ModelElement)
655: 	  p.moveToTrash(owner);
656:       }
657:     }
658:     super.actionPerformed(ae);
659:   }
