1318:     Vector sels = ce.getSelectionManager().getFigs();
1319:     java.util.Enumeration enum = sels.elements();
1320:     Vector classes = new Vector();
1321:     while (enum.hasMoreElements()) {
1322:       Fig f = (Fig) enum.nextElement();
1323:       Object owner = f.getOwner();
1324:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
1325: 	continue;
1326:       Classifier cls = (Classifier) owner;
