505:     //    catch (java.lang.ClassMismatchException ignore) {
506:     //      System.out.println("got an ClassMismatchException");
507:     //    }
508:     catch (IOException ignore) {
509:       System.out.println("got an IOException");
510:       ignore.printStackTrace();
511:     }
512:     return false;
513:   }
