581:   public void jumpToDiagramShowing(Set dms) {
582:     if (dms.size() == 0) return;
583:     Object first = dms.elementAt(0);
584:     if (first instanceof Diagram && dms.size() > 1) {
585:       setTarget(first);
586:       select(dms.elementAt(1));
587:       return;
588:     }
589:     if (first instanceof Diagram && dms.size() == 1) {
590:       setTarget(first);
591:       select(null);
592:       return;
593:     }
594:     Vector diagrams = getProject().getDiagrams();
595:     Object target = _multiPane.getTarget();
596:     if ((target instanceof Diagram) &&
597: 	((Diagram)target).countContained(dms) == dms.size()) {
598:       select(first);
599:       return;
600:     }
601: 
602:     Diagram bestDiagram = null;
603:     int bestNumContained = 0;
604:     for (int i = 0; i < diagrams.size(); i++) {
605:       Diagram d = (Diagram) diagrams.elementAt(i);
606:       int nc = d.countContained(dms);
607:       if (nc > bestNumContained) {
608: 	bestNumContained = nc;
609: 	bestDiagram = d;
610:       }
611:       if (nc == dms.size()) break;
612:     }
613:     if (bestDiagram != null) {
614:       setTarget(bestDiagram);
615:       select(first);
616:     }
617:   }
