166:     try {
167:       JFileChooser chooser = new JFileChooser();
168:       ArgoFileFilter filter = new ArgoFileFilter();
169:       chooser.addChoosableFileFilter(filter);
170:       chooser.setFileFilter(filter);
171:       int retval = chooser.showOpenDialog(pb);
172:       if(retval == 0) {
173: 	File theFile = chooser.getSelectedFile();
174: 	if(theFile != null) {
175: 	  String pathname = chooser.getSelectedFile().getAbsolutePath();
176:     	pb.showStatus("Reading " + pathname + "...");
177:     	FileInputStream fis = new FileInputStream(pathname);
178:     	ObjectInput s = new ObjectInputStream(fis);
179:     	Project p = (Project) s.readObject();
180: 	p.postLoad();
181: 	if (fis != null) fis.close();
182:     	pb.showStatus("Read " + pathname);
183: 	pb.setProject(p);
184: 	return;
185: 	}
186:       }
187:       JOptionPane.showMessageDialog(pb, "No file chosen");
188:     }
189:     catch (FileNotFoundException ignore) {
190:       System.out.println("got an FileNotFoundException");
191:      }
192:     catch (java.lang.ClassNotFoundException ignore) {
193:       System.out.println("got an ClassNotFoundException");
194:      }
195:     catch (IOException ignore) {
196:       System.out.println("got an IOException");
197:     }
198: 
199:   }
