780: class ActionGenerateOne extends UMLAction {
781:   public ActionGenerateOne() { super("Generate Selected Classes"); }
782: 
783:   public void actionPerformed(ActionEvent e) {
784:     ProjectBrowser pb = ProjectBrowser.TheInstance;
785:     Editor ce = uci.gef.Globals.curEditor();
786:     Vector sels = ce.getSelectionManager().getFigs();
787:     java.util.Enumeration enum = sels.elements();
788:     while (enum.hasMoreElements()) {
789:       Fig f = (Fig) enum.nextElement();
790:       Object owner = f.getOwner();
791:       if (!(owner instanceof MMClass) && !(owner instanceof Interface)) continue;
792:       Classifier cls = (Classifier) owner;
793:       String name = cls.getName().getBody();
794:       if (name == null || name.length() == 0) return;
795:       String path = ".";
796:       pb.showStatus("Generating source file for " + name + "...");
797:       GeneratorJava.GenerateFile(cls, path);
798:       pb.showStatus("Generating source file for " + name + "... done.");
799:       //pb.showStatus(" ");
800:     }
801:   }
802: 
803:   public boolean shouldBeEnabled() {
804:     if (!super.shouldBeEnabled()) return false;
805:     Editor ce = uci.gef.Globals.curEditor();
806:     Vector sels = ce.getSelectionManager().getFigs();
807:     java.util.Enumeration enum = sels.elements();
808:     boolean foundOne = false;
809:     while (enum.hasMoreElements()) {
810:       Fig f = (Fig) enum.nextElement();
811:       Object owner = f.getOwner();
812:       if (!(owner instanceof Classifier)) continue;
813:       Classifier cls = (Classifier) owner;
814:       String name = cls.getName().getBody();
815:       if (name == null || name.length() == 0) return false;
816:       foundOne = true;
817:     }
818:     return foundOne;
819:   }
820: } /* end class ActionGenerateOne */
