79:     // contructors
80: 
81:     /**
82:      * This constructor is used to build a dummy statechart diagram so
83:      * that a project will load properly.
84:      */
85:     public UMLStateDiagram() {
86: 
87:         try {
88:             setName(getNewDiagramName());
89:         } catch (PropertyVetoException pve) { }
90:     }
91: 
92:     /**
93:      * Constructor.
94:      *
95:      * @param namespace the NameSpace for the new diagram
96:      * @param machine the StateMachine
97:      */
98:     public UMLStateDiagram(Object namespace, Object machine) {
99:         this();
100: 
101:         if (!Model.getFacade().isAStateMachine(machine)) {
102:             throw new IllegalArgumentException();
103:         }
104: 
105:         if (machine != null && namespace == null) {
106:             Object context = Model.getFacade().getContext(machine);
107:             if (Model.getFacade().isAClassifier(context)) {
108:                 namespace = context;
109:             } else if (Model.getFacade().isABehavioralFeature(context)) {
110:                 namespace = Model.getFacade().getOwner(context);
111:                 // TODO: Find out if this would help:
112: //            } else {
113: //                namespace = 
114: //                    ProjectManager.getManager().getCurrentProject().getRoot();
115:             }
116:         }
117: 
118:         if (namespace != null && Model.getFacade().getName(namespace) != null) {
119:             if (!Model.getFacade().getName(namespace).trim().equals("")) {
120:                 String name = null;
121:                 String diagramName = Model.getFacade().getName(namespace);
122:                 int number =
123:                     (Model.getFacade().getBehaviors(namespace)) == null
124:                     ? 0
125:                             : Model.getFacade().getBehaviors(namespace).size();
126:                 name = diagramName + " " + (number++);
127:                 LOG.info("UMLStateDiagram constructor: String name = " + name);
128:                 try {
129:                     setName(name);
130:                 } catch (PropertyVetoException pve) { }
131:             }
132:         }
133:         if (namespace != null) {
134:             setup(namespace, machine);
135:         }
136:     }
137: 
138:     /**
139:      * The owner of a statechart diagram is the statechart diagram
140:      * it's showing.
141:      * @see org.argouml.uml.diagram.ui.UMLDiagram#getOwner()
142:      */
143:     public Object getOwner() {
144:         StateDiagramGraphModel gm = (StateDiagramGraphModel) getGraphModel();
145:         return gm.getMachine();
146:     }
