148:     /**
149:      * Called by the PGML parser to initialize the statechart
150:      * diagram. First the parser creates a statechart diagram via the
151:      * default constructor. Then this method is called.
152:      *
153:      * @see org.tigris.gef.base.Diagram#initialize(Object)
154:      */
155:     public void initialize(Object o) {
156:         if (Model.getFacade().isAStateMachine(o)) {
157:             Object sm = /*(MStateMachine)*/ o;
158:             Object context = Model.getFacade().getContext(sm);
159:             Object contextNamespace = null;
160:             if (Model.getFacade().isAClassifier(context)) {
161:                 contextNamespace = context;
162:             } else if (Model.getFacade().isABehavioralFeature(context)) {
163:                 contextNamespace = Model.getFacade().getNamespace(
164:                         Model.getFacade().getOwner(context));
165:             }
166:             if (contextNamespace != null) {
167:                 setup(contextNamespace, sm);
168:             }
169:         } else {
170:             throw new IllegalStateException(
171:                 "Cannot find context namespace "
172:                     + "while initializing "
173:                     + "statechart diagram");
174:         }
175:     }
