287:     public void reexpand() {
288:         if (_expandedPathsInModel == null)
289:             return;
290:         _reexpanding = true;
291:         Object[] path2 = new Object[1];
292:         path2[0] = getModel().getRoot();
293:         TreeModelEvent tme = new TreeModelEvent(this, path2, null, null);
294:         treeModelListener.treeStructureChanged(tme);
295:         treeDidChange();
296: 
297:         java.util.Enumeration enum = getExpandedPaths().elements();
298:         while (enum.hasMoreElements()) {
299:             TreePath path = (TreePath) enum.nextElement();
300:             tme = new TreeModelEvent(this, path, null, null);
301:             treeModelListener.treeStructureChanged(tme);
302:             expandPath(path);
303:             // addListenerToPath(path);
304:         }
305:         _reexpanding = false;
306: 
307:     }
